export const MYSTERY_MASS_REVIEW_DATA = Object.freeze({"version":"MYSTERY_MASS_DUAL_REVIEW_20261014","status":"EDITORIAL_REVIEW_ONLY","biblical":[{"id":"SH01","title":{"en":"Creation and worship","fr":"La création et l'offrande"},"narrative":{"en":"The problem is not why man invented sacrifice, but why the creature can owe anything to the Creator. St Alphonsus distinguishes the ends traditionally attributed to sacrifice—adoration, thanksgiving, expiation and petition—and the acts by which an offering is made. Creation makes the first two intelligible; the Fall will make the third urgent. The Eucharist is not simply the most impressive instance of an older ritual category. It is Christ's own offering, which gives the Church's thanksgiving and petition their efficacy.","fr":"Le problème n'est pas d'abord de savoir pourquoi l'homme a inventé le sacrifice, mais pourquoi la créature doit rendre un culte à son Créateur. Saint Alphonse distingue les fins traditionnelles du sacrifice — adoration, action de grâces, expiation et demande — ainsi que les actes qui constituent l'oblation. La Création fait comprendre l'adoration et la reconnaissance ; la Chute rendra nécessaire la réconciliation. L'Eucharistie ne se réduit pourtant pas à une forme supérieure des sacrifices anciens : c'est l'offrande du Christ lui-même, dans laquelle l'Église rend grâce et présente ses supplications au Père."},"transition":{"en":"At Creation, worship is an obligation and a privilege; after sin, it will also become a plea for reconciliation.","fr":"La vocation au culte précède le péché. Mais, après la Chute, l'hommage de la créature devra aussi devenir supplication pour obtenir miséricorde."},"scripture":["Genesis 1:1–31","Genesis 2:4–25"],"massOwners":["AO.CARD.012","AO.CANON.13","AO.CANON.14"],"sourceCitations":[{"title":"St Alphonsus · Sacrifice treatise §I · printed p.28–29","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"},{"title":"St Alphonsus · Sacrifice treatise §I · printed p.29","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"},{"title":"GIHR-01 · historical research","url":"https://github.com/Fulcanelli13/ad-orientem/blob/research/mystery-mass-editorial-consolidation-20261014/data/learn/research/mystery-mass-four-authors-original-source-findings-20261014.v1.json"}],"qualified":["Creation-to-Preface analogy is theological, not a biblical quotation or historical cause of a rite."],"artwork":null},{"id":"SH02","title":{"en":"Fall and promised redemption","fr":"La Chute et la promesse"},"narrative":{"en":"The Fall introduces a contradiction into human worship: the creature still owes God honour, yet can no longer approach Him as though nothing had happened. Dujardin reads the opening movement of Mass against Adam's loss of innocence. His interpretation is a spiritual lens, not the original meaning of the Roman opening prayers. The actual Confiteor and Kyrie speak of guilt and mercy, while Genesis establishes why those themes cannot be detached from the history of redemption.","fr":"Le péché introduit une contradiction dans le culte de l'homme : il demeure tenu d'honorer Dieu, mais ne peut plus s'approcher de lui comme si rien ne s'était passé. Le père Dujardin rapproche le commencement de la Messe de la perte d'innocence d'Adam. Il s'agit de sa méditation, non de l'origine historique des prières romaines. Le Confiteor exprime effectivement l'aveu des fautes ; le Kyrie implore la miséricorde. La Genèse montre pourquoi ces actes ont toute leur place dans l'histoire du salut, sans permettre d'affirmer que leurs gestes auraient été composés pour représenter la sortie du paradis."},"transition":{"en":"The first sacrifices will expose the question the Fall leaves unresolved: what makes an offering acceptable to God?","fr":"La première question laissée ouverte par la Chute est désormais celle de l'offrande agréable à Dieu : que vaut le sacrifice d'un homme blessé par le péché ?"},"scripture":["Genesis 3:1–24","Luke 18:9–14"],"massOwners":["AO.CARD.001","AO.CARD.002"],"sourceCitations":[],"qualified":["Do not state Introibo or Confiteor were composed to reenact the Fall."],"artwork":null},{"id":"SH03","title":{"en":"Abel: sacrifice, righteousness and innocent blood","fr":"Abel, la justice et le sang"},"narrative":{"en":"Abel's offering receives divine favour; the text does not explain its acceptance through a technical ritual formula. Hebrews interprets his offering in terms of faith. Gihr, reading Abel through the Roman Canon, develops a typology of the righteous offerer and the innocent blood that cries out. We must not adopt his additional conjecture that fire descended from heaven: Genesis does not say so. When Supra quae names Abel after the Consecration, it asks us to consider divine acceptance, not equality between an ancient gift and Christ Himself.","fr":"Dieu porte un regard favorable sur Abel et son offrande. Le récit de la Genèse ne donne pas de formule rituelle expliquant cette préférence ; l'Épître aux Hébreux insiste sur la foi d'Abel. Gihr, lisant le récit à la lumière du Canon romain, développe le rapprochement entre le juste qui offre et le sang innocent qui crie vers Dieu. Il faut pourtant écarter sa conjecture supplémentaire d'un feu descendu du ciel : la Genèse ne raconte rien de tel. Lorsque le Supra quae nomme Abel après la consécration, la comparaison porte sur l'accueil divin de l'offrande, non sur une égalité entre l'offrande ancienne et le Christ."},"transition":{"en":"The problem of accepted sacrifice persists, but the next figure introduces a stranger element: priesthood without the genealogy of Israel's later priests.","fr":"L'offrande du juste ouvre la question du sacrifice. Un personnage plus mystérieux permettra d'entrevoir un sacerdoce qui précède celui d'Israël."},"scripture":["Genesis 4:1–16","Hebrews 11:4","Hebrews 12:24"],"massOwners":["AO.CANON.09"],"sourceCitations":[{"title":"St Alphonsus · Short Explanation part IV · printed p.55–56","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"},{"title":"GIHR-03 · historical research","url":"https://github.com/Fulcanelli13/ad-orientem/blob/research/mystery-mass-editorial-consolidation-20261014/data/learn/research/mystery-mass-four-authors-original-source-findings-20261014.v1.json"},{"title":"GIHR-04 · historical research","url":"https://github.com/Fulcanelli13/ad-orientem/blob/research/mystery-mass-editorial-consolidation-20261014/data/learn/research/mystery-mass-four-authors-original-source-findings-20261014.v1.json"}],"qualified":["Genesis 4 does not state that fire consumed Abel's sacrifice: Gihr's fire inference is conjectural."],"artwork":null},{"id":"SH04","title":{"en":"Melchisedech: bread, wine and priesthood","fr":"Melchisédech, roi et prêtre"},"narrative":{"en":"In Genesis, Melchisedech is both king and priest; he brings forth bread and wine and blesses Abraham. The Epistle to the Hebrews returns to the brief episode to explain a priesthood fulfilled in Christ. Gihr interprets the bread and wine sacrificially, following a long Christian tradition, but Genesis 14 does not itself narrate their consecration or explicitly state that they were immolated. This distinction matters because the Mass invokes Melchisedech as a figure of the Eucharistic offering without making his rite identical with the Roman rite.","fr":"Le récit de la Genèse présente Melchisédech comme roi et prêtre du Dieu Très-Haut : il apporte du pain et du vin, puis bénit Abram. L'Épître aux Hébreux reprend ce bref épisode pour expliquer le sacerdoce accompli dans le Christ. Gihr, avec une longue tradition chrétienne, interprète le pain et le vin en termes sacrificiels. Cependant, la Genèse ne décrit ni consécration eucharistique ni immolation explicite de ces dons. La distinction permet de conserver toute la force de la figure biblique sans transformer le récit ancien en description du rite romain. Le Canon nommera Melchisédech avec Abel et Abraham."},"transition":{"en":"The mysterious priest meets Abraham before the more painful trial in which Abraham must relinquish the son of promise.","fr":"Dans l'ordre de la Genèse, la rencontre avec Melchisédech précède l'épreuve au cours de laquelle Abraham devra remettre à Dieu le fils de la promesse."},"scripture":["Genesis 14:18–20","Hebrews 7:1–17"],"massOwners":["AO.CANON.09","AO.CARD.010"],"sourceCitations":[{"title":"St Alphonsus · Sacrifice treatise §II · printed p.33","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"},{"title":"St Alphonsus · Short Explanation part IV · printed p.55–56","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"},{"title":"GIHR-02 · historical research","url":"https://github.com/Fulcanelli13/ad-orientem/blob/research/mystery-mass-editorial-consolidation-20261014/data/learn/research/mystery-mass-four-authors-original-source-findings-20261014.v1.json"},{"title":"GIHR-03 · historical research","url":"https://github.com/Fulcanelli13/ad-orientem/blob/research/mystery-mass-editorial-consolidation-20261014/data/learn/research/mystery-mass-four-authors-original-source-findings-20261014.v1.json"}],"qualified":["Genesis says he brought bread/wine, not that they were consecrated or sacrificed in a specific rite; distinguish Gihr's sacrificial inference."],"artwork":null},{"id":"SH05","title":{"en":"Abraham and Isaac: son of the promise","fr":"Abraham et le fils promis"},"narrative":{"en":"The command to offer Isaac challenges the promise made to Abraham: the son through whom the covenant is to continue appears to be demanded back. Abraham is stopped, and Isaac is not killed. Gihr and St Alphonsus read the obedience of Abraham and the beloved son carrying wood as prefiguring Christ, but this becomes intelligible only because the outcomes differ: Isaac is spared while Christ freely undergoes death. Supra quae later names Abraham's sacrifice among the accepted offerings, while the Eucharist presents the one infinitely greater sacrifice.","fr":"L'ordre de sacrifier Isaac met à l'épreuve la promesse même que Dieu a faite à Abraham : l'avenir de l'alliance semble reposer sur le fils qu'il doit abandonner. Mais Dieu arrête son geste ; Isaac n'est pas mis à mort. Gihr et saint Alphonse voient dans l'obéissance d'Abraham, dans le fils bien-aimé et dans le bois porté sur la montagne des figures du Christ. Le rapprochement tire précisément sa force de la différence entre les deux issues : Isaac est épargné, tandis que le Christ donne librement sa vie. Le Supra quae rappelle le sacrifice d'Abraham après que l'unique sacrifice du Sauveur a été rendu sacramentellement présent."},"transition":{"en":"What Abraham undergoes privately, Israel will next encounter nationally: deliverance bound to a lamb and its blood.","fr":"L'épreuve d'un père et de son fils prépare un autre signe : la délivrance de tout un peuple par le sang de l'agneau pascal."},"scripture":["Genesis 22:1–19","Romans 8:32"],"massOwners":["AO.CANON.09"],"sourceCitations":[{"title":"St Alphonsus · Short Explanation part IV · printed p.55–56","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"},{"title":"GIHR-05 · historical research","url":"https://github.com/Fulcanelli13/ad-orientem/blob/research/mystery-mass-editorial-consolidation-20261014/data/learn/research/mystery-mass-four-authors-original-source-findings-20261014.v1.json"},{"title":"GIHR-03 · historical research","url":"https://github.com/Fulcanelli13/ad-orientem/blob/research/mystery-mass-editorial-consolidation-20261014/data/learn/research/mystery-mass-four-authors-original-source-findings-20261014.v1.json"}],"qualified":["Genesis explicitly spares Isaac; do not present his immolation as completed.","Biblical order of Melchisedech and Abraham/Isaac differs from Supra quae word order."],"artwork":null},{"id":"SH06","title":{"en":"Passover: blood of deliverance","fr":"La Pâque et la délivrance"},"narrative":{"en":"In Exodus 12 the blood of a lamb identifies the households spared in the judgment upon Egypt. The meal is bound to a commanded remembrance and to the departure from bondage. St Alphonsus expressly uses the Paschal lamb among the Old Law's anticipations of Christ's sacrifice. The Christian claim is not that the Roman Agnus Dei simply quotes Exodus, but that Christ is the Paschal Lamb whose death accomplishes a deeper deliverance; the Gospel and St Paul provide the bridge.","fr":"En Égypte, le sang de l'agneau marque les maisons épargnées par le jugement, et le repas prescrit accompagne le départ d'Israël. La Pâque unit donc une délivrance, un sacrifice et une mémoire confiée aux générations suivantes. Saint Alphonse compte l'agneau pascal parmi les figures de l'offrande du Christ. Ce n'est pas dire que l'Agnus Dei romain soit simplement une citation de l'Exode. Les Évangiles et saint Paul permettent le passage vers le sens chrétien : le véritable Agneau opère par son sang une délivrance qui dépasse la sortie d'Égypte et atteint l'esclavage du péché."},"transition":{"en":"The people saved through the sea must still be sustained on their journey; redemption calls for nourishment, not deliverance alone.","fr":"Le peuple délivré doit encore traverser le désert. Il lui faut une nourriture qui lui permette de poursuivre sa route vers l'héritage promis."},"scripture":["Exodus 12:1–28","1 Corinthians 5:7"],"massOwners":["AO.CANON.07","AO.CARD.021"],"sourceCitations":[{"title":"St Alphonsus · Sacrifice treatise §I · printed p.30","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"}],"qualified":["Do not assert the entire Roman Agnus Dei text is transcribed from Exodus."],"artwork":null},{"id":"SH07","title":{"en":"Manna: food in the wilderness","fr":"La manne et le pain du ciel"},"narrative":{"en":"The manna is a gift for a pilgrim people, neither earned nor supplied by their own resources. Yet those who ate it still died. In John 6, Christ sets the true Bread from heaven in deliberate contrast with the manna: His gift is not merely provisional bodily sustenance. The Eucharistic application must be presented through Christ's discourse and Catholic sacramental teaching rather than pretending that Exodus already describes the consecrated Host. This stage prepares Communion, without collapsing the distinction between Israel's history and the sacrament.","fr":"La manne vient soutenir un peuple pèlerin qui ne saurait se nourrir par ses propres forces. Mais ceux qui en mangent demeurent mortels. Dans le discours du Pain de vie, le Christ oppose à cet aliment provisoire le don de sa propre chair pour la vie du monde. Le rapport entre les deux textes doit être établi par les paroles du Seigneur et par la doctrine catholique de l'Eucharistie : l'Exode ne décrit pas déjà une hostie consacrée. Cette étape prépare la compréhension de la communion sacramentelle, tout en préservant le sens historique du séjour d'Israël au désert."},"transition":{"en":"Food for the journey is followed by covenant: a relationship formally sealed with blood.","fr":"Après la nourriture du désert vient le sang de l'Alliance : la délivrance et la marche ne sont pas séparables d'une relation solennelle avec Dieu."},"scripture":["Exodus 16:1–36","John 6:31–58"],"massOwners":["AO.CARD.023","AO.CARD.025"],"sourceCitations":[],"qualified":[],"artwork":null},{"id":"SH08","title":{"en":"Sinai: covenant sealed in blood","fr":"L'Alliance scellée dans le sang"},"narrative":{"en":"At Sinai, the people assent to the words of the covenant and Moses applies blood in its solemn confirmation. Jeremiah promises a new covenant, not simply a renewal of compliance with the former one. At the Last Supper Christ speaks of His Blood in connection with the new covenant. St Alphonsus reads this in light of the Eucharistic institution and its sacrificial fulfilment. The chalice formula of the 1962 Roman Missal has its own received wording; it is not a quotation copied without change from one biblical account.","fr":"Au Sinaï, le peuple accepte les paroles de l'Alliance, et Moïse en confirme solennellement l'engagement avec le sang sacrificiel. Jérémie annoncera cependant une Alliance nouvelle, inscrite dans les cœurs et liée au pardon des péchés. À la dernière Cène, le Christ parle de son Sang comme du Sang de cette nouvelle Alliance. Saint Alphonse relie la promesse prophétique à l'institution eucharistique et à l'accomplissement du sacrifice. La formule du calice dans le Missel romain de 1962 conserve son texte liturgique propre : il ne faut pas la remplacer par les mots d'un seul récit évangélique."},"transition":{"en":"The covenant also requires an ordered life of worship: altar, sanctuary, priest and appointed sacrifice.","fr":"L'Alliance comporte aussi un culte ordonné : un autel, un sanctuaire, des prêtres et des sacrifices déterminés."},"scripture":["Exodus 24:3–8","Jeremiah 31:31–34","Luke 22:20"],"massOwners":["AO.CANON.07"],"sourceCitations":[{"title":"St Alphonsus · Sacrifice treatise §II · printed p.34–36","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"}],"qualified":["1962 chalice formula includes wording not identical with any single Evangelist; no wholesale Scripture replacement."],"artwork":null},{"id":"SH09","title":{"en":"Sanctuary and ministerial priesthood","fr":"Le sanctuaire et le sacerdoce"},"narrative":{"en":"The tabernacle and the later Temple teach that access to God's presence is never treated as a casual activity. Priestly mediation and sacrifice are part of Israel's worship, but the Letter to the Hebrews explains both their dignity and their insufficiency compared with Christ's priesthood. St Alphonsus uses Levitical figures, while later commentators sometimes connect the priest's extended hands at Hanc igitur with the imposition of hands upon a victim. This is symbolic interpretation, not a demonstrable explanation of the gesture's Roman origin. The live scapegoat of Leviticus 16 is sent away rather than slain.","fr":"Le Tabernacle, puis le Temple, manifestent que la présence divine ne se traite jamais avec désinvolture. Le sacerdoce et les sacrifices de l'ancienne Loi ont leur dignité ; l'Épître aux Hébreux en explique aussi les limites devant le sacerdoce du Christ. Saint Alphonse reprend plusieurs figures lévitiques. D'autres commentateurs rapprochent les mains étendues du prêtre au Hanc igitur de l'imposition des mains sur une victime. Le rapprochement peut éclairer la méditation sans établir l'origine historique du geste romain. Dans le Lévitique, le bouc vivant du rite d'expiation est envoyé au désert : il n'est pas immolé."},"transition":{"en":"The prophet who sees God's throne hears a hymn that the Roman Mass will actually take into its own words.","fr":"Le prophète admis devant le trône divin entendra des paroles que l'Église reprendra réellement dans sa propre prière."},"scripture":["Exodus 25:1–9","Leviticus 16:1–34","Hebrews 9:1–14"],"massOwners":["AO.CARD.010","AO.CANON.04","AO.CARD.011"],"sourceCitations":[{"title":"St Alphonsus · Sacrifice treatise §I · printed p.27–28","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"},{"title":"St Alphonsus · Short Explanation part IV · printed p.50–51","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"},{"title":"TORMA-01 · historical research","url":"https://github.com/Fulcanelli13/ad-orientem/blob/research/mystery-mass-editorial-consolidation-20261014/data/learn/research/mystery-mass-four-authors-original-source-findings-20261014.v1.json"}],"qualified":["The live scapegoat of Leviticus 16 is sent away, not sacrificed in the rite; don't infer historical origin of Hanc igitur's hand extension from an analogy."],"artwork":null},{"id":"SH10","title":{"en":"Isaiah's heavenly worship","fr":"La sainteté proclamée par Isaïe"},"narrative":{"en":"Isaiah's vision begins not with a description of a temple object but with the holiness of the Lord before whom even the seraphim veil themselves. The Sanctus draws upon this proclamation, joined in Christian worship with the acclamation addressed to Christ on His entry into Jerusalem. The two sources should remain visible. The liturgical text speaks with Scripture's language but is not a continuous quotation from a single episode. The difference between vision and liturgical adaptation is itself a fruitful matter for contemplation.","fr":"La vision d'Isaïe met d'abord l'homme en présence de la sainteté du Seigneur. Les séraphins se voilent et proclament sa gloire. Le Sanctus reprend cette acclamation et lui joint la bénédiction adressée au Christ lors de son entrée à Jérusalem. Ces deux situations bibliques doivent rester distinctes : la prière romaine rassemble leurs paroles sans former la citation continue d'un seul récit. Cette adaptation liturgique mérite elle-même d'être contemplée, car elle unit la louange céleste et l'accueil du Seigneur qui vient. Le détail des mots et de leur histoire appartient à l'étude du Sanctus."},"transition":{"en":"The same prophet also announces a suffering servant; heavenly holiness will be approached through the sufferings of the innocent.","fr":"Le prophète qui a vu la sainteté de Dieu parlera aussi du Serviteur souffrant : le salut passera par l'obéissance et la douleur de l'innocent."},"scripture":["Isaiah 6:1–8","Revelation 4:8"],"massOwners":["AO.CARD.013"],"sourceCitations":[],"qualified":["Vulgate Isaiah says Dominus Deus exercituum; Roman Sanctus uses Deus Sabaoth, an adapted witness."],"artwork":null},{"id":"SH11","title":{"en":"Suffering Servant: the innocent victim","fr":"Le Serviteur souffrant"},"narrative":{"en":"Isaiah's suffering servant bears the iniquities of many without simply being one more animal substitute. St Alphonsus considers such prophecies within the older law's sacrificial figures and turns to Hebrews to explain their fulfilment. The decisive claim of Christian sacrificial theology is that Christ's obedience and self-offering exceed every previous victim. The narrative must let the biblical passage speak in its own context before explaining the Church's interpretation of it as a prophecy of the Passion and its relation to Mass.","fr":"Isaïe présente un Serviteur qui porte les fautes d'autrui et se livre sans répondre à la violence. Saint Alphonse rapproche cette prophétie des figures sacrificielles de l'ancienne Loi, puis se tourne vers l'Épître aux Hébreux pour en montrer l'accomplissement. Le sens chrétien n'est pas que le Christ aurait accompli simplement un sacrifice animal plus parfait selon les mêmes modalités matérielles : son obéissance personnelle et son offrande de lui-même dépassent les anciennes victimes. Il convient de lire d'abord le passage prophétique dans son contexte, puis d'examiner avec les Pères et la théologie de l'Église son accomplissement dans la Passion et dans la Messe."},"transition":{"en":"With the need for a definitive sacrifice revealed, prophecy turns outward toward an offering made among the nations.","fr":"La nécessité d'un sacrifice définitif une fois reconnue, la prophétie annonce aussi une offrande pure rendue à Dieu parmi les nations."},"scripture":["Isaiah 52:13–15","Isaiah 53:1–12"],"massOwners":["AO.CANON.06","AO.CANON.07","AO.CARD.021"],"sourceCitations":[{"title":"St Alphonsus · Sacrifice treatise §I · printed p.27–28","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"},{"title":"St Alphonsus · Sacrifice treatise §I · printed p.28–29","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"}],"qualified":["Use controlled doctrinal sources for Eucharistic presence of once-for-all sacrifice; not mere pictorial analogy."],"artwork":null},{"id":"SH12","title":{"en":"Prophecy of the pure offering","fr":"L'offrande pure annoncée"},"narrative":{"en":"Malachi's announcement of a pure offering among the nations belongs first to the prophet's rebuke of corrupt worship. Christian tradition reads its universality and purity in relation to the Eucharistic Sacrifice. Le Brun's preliminary treatise specifically moves from the sacrifices of the old dispensation to Christ, their fulfilment, and then to the Mass. This is a theological reading within tradition, not the claim that the prophet described the Roman Missal's future gestures or textual formulas.","fr":"Chez Malachie, l'annonce d'une offrande pure offerte parmi les nations appartient d'abord à une dénonciation des sacrifices accomplis sans fidélité. La tradition chrétienne reconnaît dans l'universalité et la pureté de cette offrande une annonce du sacrifice eucharistique. Le Brun organise précisément son traité préliminaire autour de l'histoire des sacrifices et de leur accomplissement dans le Christ, avant d'exposer les cérémonies de la Messe. Il faut présenter ce cheminement comme une lecture théologique traditionnelle, et non comme si Malachie avait déjà décrit les signes de croix, les inclinations ou les paroles du Missel romain."},"transition":{"en":"The promise now ceases to be merely a figure or oracle: the divine Son assumes the nature in which He can offer Himself.","fr":"La promesse va maintenant prendre chair : le Fils éternel reçoit la nature humaine dans laquelle il pourra s'offrir au Père."},"scripture":["Malachi 1:11","Hebrews 10:1–18"],"massOwners":["AO.CARD.011","AO.CANON.01"],"sourceCitations":[{"title":"St Alphonsus · Sacrifice treatise §I · printed p.28–29","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"}],"qualified":["A Christian traditional reading must be identified as such; don't present modern sacrificial practice as described literally in Malachi."],"artwork":null},{"id":"SH13","title":{"en":"Annunciation and Incarnation","fr":"L'Incarnation et la Victime préparée"},"narrative":{"en":"At the Annunciation, the eternal Son becomes man without ceasing to be God. St Alphonsus treats the Incarnation as the preparation of the victim who will offer Himself freely: a human body is taken for the accomplishment of the Father's will, as Hebrews interprets the mystery. This does not mean the historical sacrifice of Calvary is already finished at Nazareth. The Mass's Credo and the Last Gospel confess the Incarnation in different ritual positions, but the salvation-history journey encounters it at the historical beginning of Christ's earthly life.","fr":"À l'Annonciation, le Fils éternel de Dieu devient homme sans cesser d'être Dieu. Saint Alphonse explique l'Incarnation comme la préparation de Celui qui s'offrira librement : le corps assumé rend possible l'accomplissement humain de la volonté du Père, à la lumière de l'Épître aux Hébreux. Cela ne signifie pas que le sacrifice historique du Calvaire serait déjà consommé à Nazareth. Le Credo et le dernier Évangile confessent l'Incarnation à des endroits différents de l'ordre liturgique ; la chronologie biblique la rencontre, elle, au commencement de la vie terrestre du Sauveur. Cette dissymétrie est essentielle à nos deux parcours."},"transition":{"en":"The birth of the Word in the flesh is greeted with praise that will become the opening words of a much longer liturgical hymn.","fr":"La naissance du Verbe fait chair sera accueillie par une louange qui deviendra les premiers mots de l'hymne liturgique du Gloria."},"scripture":["Luke 1:26–38","John 1:1–14","Hebrews 10:5–10"],"massOwners":["AO.CARD.009","AO.CARD.030"],"sourceCitations":[{"title":"St Alphonsus · Sacrifice treatise §II · printed p.31–32","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"},{"title":"St Alphonsus · Sacrifice treatise §II · printed p.32","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"}],"qualified":["Last Gospel is conditional; do not infer its universal use from narrative structure."],"artwork":null},{"id":"SH14","title":{"en":"Nativity and angelic Gloria","fr":"La Nativité et le Gloria"},"narrative":{"en":"The Gloria begins with the proclamation heard by the shepherds at Bethlehem. St Alphonsus notes the scriptural opening, but the hymn that follows is the Church's developed act of praise and petition, not an unaltered transcript of the angels' song. The Nativity therefore contributes actual language to the Mass while the later liturgical text expands its scope to adoration of the Trinity and supplication to the Lamb. This is a stronger connection than treating the priest's posture as an imitation of a shepherd.","fr":"Le Gloria commence par l'acclamation que les bergers entendent à Bethléem. Saint Alphonse remarque l'origine évangélique de ces paroles, mais l'hymne qui suit est une prière développée par l'Église : elle n'est pas la transcription inchangée du chant des anges. La Nativité fournit donc à la Messe des mots bibliques effectivement repris, tandis que le texte liturgique les prolonge en adoration, action de grâces et supplication adressées à Dieu. Cette relation est plus solide que l'idée d'un geste sacerdotal qui représenterait matériellement l'attitude d'un berger. L'histoire du Gloria et ses omissions prescrites doivent être examinées dans le parcours descriptif."},"transition":{"en":"The child announced as Saviour will be identified publicly as the Lamb whose sacrifice removes sin.","fr":"L'Enfant annoncé comme Sauveur sera publiquement désigné comme l'Agneau de Dieu, celui qui enlève les péchés du monde."},"scripture":["Luke 2:1–20"],"massOwners":["AO.CARD.003"],"sourceCitations":[{"title":"St Alphonsus · Short Explanation part II · printed p.42–43","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"}],"qualified":["Latin Luke 2:14 differs from the Roman Gloria's opening phrase; do not certify literal identity."],"artwork":null},{"id":"SH15","title":{"en":"John the Baptist calls Christ the Lamb","fr":"Voici l'Agneau de Dieu"},"narrative":{"en":"John the Baptist's testimony, 'Lamb of God', is not a general image of innocence. Heard after the Passover narratives and the prophets, it identifies Jesus as the one through whom sin is taken away. The Roman Agnus Dei reuses the Baptist's words but extends them into petitions for mercy and, ordinarily, peace. Their location before Communion belongs to the liturgical arrangement; their theological force comes from the identity of the sacrificed and living Christ.","fr":"Le témoignage de saint Jean-Baptiste ne fait pas de l'agneau une simple image de douceur. Après les récits de la Pâque et les paroles des prophètes, ce nom désigne Jésus comme Celui par qui le péché est enlevé. L'Agnus Dei reprend les paroles du Précurseur, mais les développe en supplications de miséricorde et, ordinairement, de paix. Leur place avant la communion appartient à l'ordonnance liturgique. Leur sens théologique repose sur l'identité du Christ, immolé pour le salut du monde et désormais vivant. Les formes propres aux messes des défunts exigent une explication distincte."},"transition":{"en":"The Lord whom John identifies will also speak of a bread from heaven radically unlike Israel's temporary nourishment.","fr":"Celui que Jean désigne comme Agneau parlera bientôt d'un pain venu du ciel, autrement véritable que la nourriture passagère d'Israël."},"scripture":["John 1:29–36"],"massOwners":["AO.CARD.021","AO.CARD.024"],"sourceCitations":[],"qualified":["Mass Agnus Dei petitions are liturgical adaptation; distinguish Requiem form."],"artwork":null},{"id":"SH16","title":{"en":"Christ the living Bread","fr":"Le Pain de vie et l'humilité du centurion"},"narrative":{"en":"In John 6, Christ links His identity as living Bread with the gift of His flesh for the life of the world; the discourse must be read in full, including the objections and the departure of many listeners. It is not a miniature account of the rite of Communion. The Mass later gives a sacramental form to receiving Christ. The centurion's statement in Matthew 8 supplies a second, different scriptural connection: the Church adapts the language of a servant's healing into the communicant's humble confession of unworthiness.","fr":"Dans le sixième chapitre de saint Jean, le Christ annonce la nourriture qu'il donne pour la vie du monde. Il faut lire le discours dans son ensemble, y compris les objections et le départ de nombreux auditeurs. Il ne s'agit pas d'un petit manuel des gestes de la communion. Le rapprochement eucharistique demande l'étude du récit et de la doctrine sacramentelle. Une seconde correspondance provient du centurion de l'Évangile selon saint Matthieu : la liturgie adapte ses paroles sur la guérison d'un serviteur en confession personnelle d'indignité avant de recevoir le Christ. Ce n'est donc pas une citation inchangée du récit."},"transition":{"en":"Christ's approaching entry into Jerusalem sets the final sequence of His public ministry in motion.","fr":"L'entrée du Seigneur à Jérusalem ouvre le dernier mouvement de sa vie publique et conduit au mystère de son sacrifice."},"scripture":["John 6:25–59","Matthew 8:5–13"],"massOwners":["AO.CARD.022","AO.CARD.023","AO.CARD.024","AO.CARD.025"],"sourceCitations":[{"title":"St Alphonsus · Sacrifice treatise §II · printed p.34–36","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"}],"qualified":["Matthew 8:8 speaks of the servant; liturgy changes to anima mea.","Priest and faithful have separate liturgical Domine non sum dignus contexts."],"artwork":null},{"id":"SH17","title":{"en":"Entry into Jerusalem and Benedictus","fr":"L'entrée à Jérusalem et le Benedictus"},"narrative":{"en":"The crowd's cry when Christ enters Jerusalem includes 'Blessed is he who comes in the name of the Lord.' Within the Sanctus the Church places that acclamation after Isaiah's heavenly hymn. The juxtaposition matters: worshippers bless the coming Messiah while joining the worship of heaven. But the Mass does not present Palm Sunday as though it occurred after Isaiah's vision in one biblical narrative. The two biblical moments are joined liturgically; in this journey, they remain chronologically distinct.","fr":"La foule acclame le Christ à son entrée à Jérusalem par la bénédiction adressée à Celui qui vient au nom du Seigneur. Dans la Messe, l'Église joint cette acclamation au Sanctus inspiré de la vision d'Isaïe. La juxtaposition est décisive : on accueille le Messie tout en s'unissant à l'adoration céleste. Il ne faut pourtant pas lire ces deux passages comme si Isaïe et la procession des Rameaux appartenaient au même épisode biblique. Leur union est liturgique ; le parcours chronologique garde leur séparation historique. L'étude du Sanctus explique comment et pourquoi les mots ont été associés."},"transition":{"en":"The Lord's arrival leads to the institution of the Eucharist in anticipation of His Passion.","fr":"L'entrée dans la ville mène à l'institution de l'Eucharistie, anticipation sacramentelle de la Passion désormais proche."},"scripture":["Matthew 21:1–11","Isaiah 6:3"],"massOwners":["AO.CARD.013"],"sourceCitations":[],"qualified":["Do not treat Sanctus and Benedictus as a single biblical quotation."],"artwork":null},{"id":"SH18","title":{"en":"The Last Supper and Eucharistic institution","fr":"La dernière Cène et l'institution eucharistique"},"narrative":{"en":"The evangelists and St Paul witness Christ giving bread and wine as His Body and Blood and commanding the memorial. St Alphonsus treats the Last Supper in explicit relation to sacrifice and the Church's Eucharistic participation; he also distinguishes his own conclusion from an anonymous French writer's account of sacrificial consummation. A serious treatment must preserve this disagreement rather than smoothing it into a single inherited explanation. The sacramental institution anticipates and is inseparable from Calvary, without multiplying historical sacrifices.","fr":"Les Évangiles et saint Paul attestent que le Christ donne le pain et le vin comme son Corps et son Sang, puis confie aux apôtres la mémoire sacramentelle de son offrande. Saint Alphonse examine la Cène dans son rapport à la Croix et à la participation eucharistique de l'Église. Il répond aussi à un auteur français anonyme dont l'explication place autrement l'accomplissement de certains actes sacrificiels. Il faut conserver cette différence d'interprétation plutôt que fabriquer une unanimité. L'institution anticipe le Calvaire et lui demeure inséparable ; elle ne multiplie pas pour autant les sacrifices historiques de Jésus-Christ."},"transition":{"en":"The freedom of Christ's offering becomes manifest when He accepts the Father's will in Gethsemane.","fr":"L'offrande du Christ est libre. Cette volonté apparaît avec une gravité particulière lorsqu'il accepte la Passion dans le jardin de Gethsémani."},"scripture":["Luke 22:14–20","1 Corinthians 11:23–26"],"massOwners":["AO.CANON.06","AO.CANON.07","AO.CANON.08"],"sourceCitations":[{"title":"St Alphonsus · Sacrifice treatise §II · printed p.34–36","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"}],"qualified":["1962 Missal consecration text is its own controlled witness; don't replace with Gospel wording.","Do not narrate a second independent sacrifice separate from Calvary."],"artwork":null},{"id":"SH19","title":{"en":"Gethsemane and voluntary oblation","fr":"Gethsémani et l'obéissance"},"narrative":{"en":"Gethsemane shows that Christ's sacrifice is voluntary obedience, not merely suffering inflicted by others. Hebrews interprets the saving efficacy of His offering through the obedience of His will. St Alphonsus traces the sacrificial purpose of the Incarnation toward this consent and its fulfilment; the Passion-meditation methods of later writers associate particular Mass gestures with this scene. Such associations may aid prayer, but they must remain optional, explicitly attributed, and separate from the historical cause of the gestures.","fr":"À Gethsémani, Jésus-Christ accepte librement la volonté du Père. L'efficacité de son sacrifice ne vient donc pas seulement des souffrances que d'autres lui infligent : elle est inséparable de son obéissance et de son amour. Saint Alphonse suit la finalité sacrificielle de l'Incarnation jusqu'à cet assentiment et à son accomplissement. Les méthodes de méditation de la Passion proposées par des auteurs spirituels rattachent parfois certains gestes de la Messe à l'agonie au jardin. Ces rapprochements peuvent nourrir la prière, mais ils doivent conserver leur auteur, demeurer facultatifs et ne jamais se substituer à l'histoire réelle des rites."},"transition":{"en":"The obedience accepted in the garden is consummated on Calvary, where all the earlier sacrificial figures are judged by their fulfilment.","fr":"Ce que le Fils consent à offrir dans le jardin sera accompli au Calvaire, où toutes les figures anciennes trouvent leur mesure véritable."},"scripture":["Matthew 26:36–46","Philippians 2:5–11"],"massOwners":["AO.CARD.010","AO.CANON.04"],"sourceCitations":[{"title":"St Alphonsus · Sacrifice treatise §I · printed p.28–29","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"},{"title":"St Alphonsus · Sacrifice treatise §II · printed p.32","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"},{"title":"TORMA-01 · historical research","url":"https://github.com/Fulcanelli13/ad-orientem/blob/research/mystery-mass-editorial-consolidation-20261014/data/learn/research/mystery-mass-four-authors-original-source-findings-20261014.v1.json"}],"qualified":["Dujardin/Francis-de-Sales style analogies are not ceremony history.","Time/order cannot be forced to match the liturgy."],"artwork":null},{"id":"SH20","title":{"en":"Calvary: the unique and perfect sacrifice","fr":"Le Calvaire, sacrifice unique et parfait"},"narrative":{"en":"At Calvary, the true Priest is also the Victim. St Alphonsus sets out the actions traditionally analysed in sacrifice and insists on Christ's once-for-all self-offering, then explains the Eucharist as sacramental participation in that same offering. He argues specifically against locating the fulfilment of every sacrificial act solely in Christ's glorification; the Eucharistic Communion matters to his account. Le Brun likewise makes Christ's unique sacrifice the point toward which prior sacrifices converge. In Mass the one offering is present sacramentally, not repeated as another execution.","fr":"Au Calvaire, le véritable Prêtre est aussi la Victime. Saint Alphonse examine les actes constitutifs du sacrifice et souligne la valeur de l'offrande accomplie une fois pour toutes par le Christ. Il explique ensuite comment l'Eucharistie donne à l'Église de participer sacramentellement à ce même sacrifice. Il discute expressément une théorie qui placerait l'accomplissement de tous les actes sacrificiels dans la seule glorification du Christ : la communion eucharistique tient une place importante dans sa propre argumentation. Le Brun fait également converger les sacrifices anciens vers celui du Sauveur. La Messe ne répète pas une nouvelle exécution sanglante."},"transition":{"en":"The Resurrection does not cancel the Cross; it reveals that the offering of the crucified Lord is victorious and enduring.","fr":"La Résurrection n'annule pas la Croix : elle manifeste la victoire du Crucifié et la permanence de la fécondité de son offrande."},"scripture":["John 19:17–30","Hebrews 9:11–28"],"massOwners":["AO.CANON.06","AO.CANON.07","AO.CANON.08","AO.CARD.011"],"sourceCitations":[{"title":"St Alphonsus · Sacrifice treatise §I · printed p.29","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"},{"title":"St Alphonsus · Sacrifice treatise §II · printed p.32","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"},{"title":"St Alphonsus · Sacrifice treatise §II · printed p.34–36","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"}],"qualified":["Avoid reenactment language, additional crucifixions, or claims that consecrated species are actually separated in the glorified Christ."],"artwork":null},{"id":"SH21","title":{"en":"Resurrection and Emmaus","fr":"La Résurrection et Emmaüs"},"narrative":{"en":"The risen Christ opens the Scriptures to the disciples on the road to Emmaus. Their retrospective understanding parallels the reader's task in the biblical journey: to discern the fulfilment of the earlier figures without rewriting them as if their authors had already seen every later rite. The Canon explicitly remembers the Resurrection in Unde et memores. The connection between Emmaus and Eucharistic Communion is a traditional interpretive reading, but the breaking of bread in Luke 24 cannot by itself be treated as a documentary account of the Roman Mass.","fr":"Sur le chemin d'Emmaüs, le Ressuscité ouvre les Écritures à ses disciples. Leur compréhension rétrospective fournit une image de la méthode de ce parcours biblique : reconnaître l'accomplissement des figures anciennes sans faire comme si leurs auteurs avaient déjà connu toutes les cérémonies romaines. Le Canon rappelle explicitement la Résurrection dans l'Unde et memores. Le rapprochement entre la fraction du pain à Emmaüs et la communion eucharistique appartient à une tradition d'interprétation ; le seul récit de saint Luc ne suffit pas à prouver que cet épisode décrive déjà la Messe romaine."},"transition":{"en":"The risen Lord ascends; His priesthood does not cease with His visible departure.","fr":"Le Ressuscité monte vers le Père. Sa disparition du regard des apôtres n'est pas la fin de son sacerdoce ni de son intercession."},"scripture":["Luke 24:13–35","1 Corinthians 15:1–11"],"massOwners":["AO.CANON.08","AO.CARD.025"],"sourceCitations":[{"title":"St Alphonsus · Sacrifice treatise §II · printed p.33–34","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"},{"title":"St Alphonsus · Sacrifice treatise §II · printed p.34–36","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"}],"qualified":["Emmaus does not independently prove that the breaking of bread in that episode is the Mass rite."],"artwork":null},{"id":"SH22","title":{"en":"Ascension and permanent priestly mediation","fr":"L'Ascension et le sacerdoce éternel"},"narrative":{"en":"Christ enters the heavenly sanctuary as the enduring High Priest. St Alphonsus's presentation of priesthood according to Melchisedech links the Psalm and Hebrews, while his reading of Supplices te rogamus records disagreement about the holy Angel: is the figure Christ Himself or angelic ministry carrying the Church's prayers? His own preference should not be attributed to the other interpreter. Nothing in this prayer requires imagining that the consecrated elements are physically transported to heaven.","fr":"Le Christ entre dans le sanctuaire céleste en Grand Prêtre dont le sacerdoce demeure. Saint Alphonse éclaire la relation entre le psaume sur Melchisédech et l'Épître aux Hébreux. À propos du Supplices te rogamus, il rapporte aussi une divergence : l'« Ange » désigne-t-il le Christ, ou bien un ministère angélique présentant les prières de l'Église ? Saint Alphonse préfère une explication rattachée à saint Thomas, qu'il faut distinguer de celle de son prédécesseur français. Rien n'autorise à imaginer que les espèces consacrées quitteraient matériellement l'autel terrestre pour être transportées au ciel."},"transition":{"en":"The exalted Lord sends the Holy Ghost and establishes the Church's continuing sacramental life on earth.","fr":"Le Seigneur glorifié envoie l'Esprit Saint et la vie sacramentelle de l'Église se déploie parmi les hommes."},"scripture":["Acts 1:6–12","Hebrews 7:23–28"],"massOwners":["AO.CANON.08","AO.CANON.10"],"sourceCitations":[{"title":"St Alphonsus · Sacrifice treatise §II · printed p.33","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"},{"title":"St Alphonsus · Short Explanation part IV · printed p.56–57","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"}],"qualified":["Supplices holy Angel interpretations are contested and should be named by author; no physical transport of species."],"artwork":null},{"id":"SH23","title":{"en":"Pentecost and the Church's Eucharistic life","fr":"La Pentecôte et la vie de l'Église"},"narrative":{"en":"Pentecost forms a worshipping, teaching Church. The primitive community is described as persevering in the apostles' teaching, fellowship, breaking of bread and prayers. In the Roman Canon, the petitions for the living and the remembrance of saints make sense within this ecclesial unity. Dujardin meditates on Pentecost near the end of Mass, but that spiritual association does not establish an apostolic origin for the priest's final blessing. The Church's Eucharistic life is historical; the private meditation is interpretive.","fr":"À la Pentecôte, l'Esprit Saint rassemble une Église qui persévère dans l'enseignement des apôtres, la communion fraternelle, la fraction du pain et les prières. Les intercessions du Canon pour les vivants et la mémoire des saints s'éclairent à partir de cette unité ecclésiale. Le père Dujardin rapproche spirituellement la bénédiction finale de l'envoi de l'Esprit, sans que cette association suffise à établir une origine apostolique du geste. Il faut distinguer soigneusement l'histoire attestée de la communauté chrétienne et les méditations particulières que les auteurs placent au fil des cérémonies."},"transition":{"en":"The Church's sacramental worship anticipates a final communion that the Apocalypse portrays through the Lamb and heavenly worship.","fr":"Le culte sacramentel de l'Église en pèlerinage annonce une communion définitive que l'Apocalypse présente sous les images de l'Agneau et de la cité céleste."},"scripture":["Acts 2:1–47","1 Corinthians 10:16–17"],"massOwners":["AO.CANON.01","AO.CANON.03","AO.CARD.025"],"sourceCitations":[{"title":"St Alphonsus · Short Explanation part IV · printed p.58–59","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"}],"qualified":["Pentecost cannot be used to prove arbitrary late rituals' apostolic origins."],"artwork":null},{"id":"SH24","title":{"en":"The Lamb and heavenly Jerusalem","fr":"L'Agneau et la Jérusalem céleste"},"narrative":{"en":"The Apocalypse portrays heavenly worship around the Lamb and a future marriage supper. These images are not a coded description of a terrestrial Roman Mass, yet the Church has long understood her Eucharistic offering and Communion in relation to Christ's heavenly priesthood. St Alphonsus expressly debates where the language of sacrificial completion belongs, warning against treating glorification and Eucharistic participation as interchangeable accounts. The final vision is the goal of the pilgrimage, not a historical episode already completed on a biblical calendar.","fr":"L'Apocalypse présente l'adoration céleste autour de l'Agneau et les noces annoncées à la fin des temps. Ce langage visionnaire n'est pas une description codée d'une Messe romaine terrestre. Il permet toutefois de comprendre que le sacrifice et la communion eucharistiques s'ordonnent au sacerdoce du Christ glorifié et à la communion définitive avec Dieu. Saint Alphonse discute précisément où situer l'accomplissement des actes sacrificiels : sa réponse ne confond pas la glorification du Sauveur avec la participation sacramentelle de l'Église. Le terme du parcours est l'espérance des biens futurs, non un événement déjà placé sur une carte historique."},"transition":{"en":"The narrative returns to Creation: man's end is communion with God, now understood through the saving priesthood and sacrifice of Christ.","fr":"Le récit rejoint son commencement : l'homme créé pour Dieu trouve dans le Christ la voie de la communion éternelle."},"scripture":["Revelation 4:1–11","Revelation 19:6–9","Revelation 21:1–27"],"massOwners":["AO.CARD.013","AO.CANON.10","AO.CANON.14","AO.CARD.025"],"sourceCitations":[{"title":"St Alphonsus · Sacrifice treatise §II · printed p.33–34","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"},{"title":"St Alphonsus · Sacrifice treatise §II · printed p.34–36","url":"https://www.papastronsay.com/publications/library/Saint%20Alphonsus/the_holy_mass.pdf"}],"qualified":["Distinguish prophetic vision and future consummation from past-event timeline.","Do not depict angel physically lifting consecrated species into heaven."],"artwork":null}],"liturgical":[{"id":"AO.CARD.001","title":"Introit & Preparatory Prayers","studies":[{"id":"MM-PRIMARY-MB02","short":{"en":"Psalm 42 turns the approach to the altar into a prayer of trust, where its recitation is prescribed. [Scripture](https://www.newadvent.org/bible/psa042.htm).","fr":"Le psaume 42 fait de l'approche de l'autel un acte de confiance, là où les rubriques le prescrivent. [Écriture](https://www.newadvent.org/bible/psa042.htm)."},"deep":{"en":"The priest approaches the altar with the words of Psalm 42: “Introibo ad altare Dei.” The psalmist asks God's light and truth to lead him to God's dwelling despite trial and sorrow. The preparation for Mass thus becomes an act of trust: one approaches God to receive his mercy and praise him. Under the 1962 rubrics this psalm is not recited at every Mass, including Masses for the Dead. [Scripture](https://www.newadvent.org/bible/psa042.htm) · [Original 1962 Roman Missal page](https://gregobase.selapa.net/sources/42/298.png).","fr":"Le prêtre s’avance vers l’autel en faisant sienne la prière du psaume 42 : « Introibo ad altare Dei ». Le psalmiste demande que la lumière et la vérité de Dieu le conduisent vers sa demeure, malgré l’épreuve et la tristesse. La préparation de la Messe devient ainsi un acte de confiance : on approche de Dieu pour recevoir sa miséricorde et le louer. Ce psaume n’est pas récité à toutes les Messes de 1962, notamment aux Messes des défunts. [Écriture](https://www.newadvent.org/bible/psa042.htm) · [Missel romain de 1962, page originale](https://gregobase.selapa.net/sources/42/298.png)."}}],"canon":null,"biblicalScenes":["SH02"],"scripture":["Luke 18:13"],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"},{"title":"Lanslots · Illustrated Explanation (1897)","url":"https://archive.org/stream/illustratedexpla00lans/illustratedexpla00lans_djvu.txt"}],"special":["PSALM_42_CONDITIONAL_FOR_REQUIEM_AND_PASSIONTIDE","PRE_MASS_CONDITIONS_MUST_USE_NORMATIVE_SOURCE"]},{"id":"AO.CARD.002","title":"Kyrie","studies":[{"id":"MM-NEW-01","short":{"en":"Mercy at the threshold [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"La miséricorde au seuil de la Messe [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."},"deep":{"en":"The repeated Kyrie is the Church's appeal to the Lord's mercy, not a mere pause before the Gloria. The cries of those who begged Christ for mercy in the Gospel show the faith and need with which we can make this prayer our own. [1962 rite](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Scripture](https://www.newadvent.org/bible/mat020.htm).","fr":"Le Kyrie répété est la supplication de l'Église à la miséricorde du Seigneur, non une simple attente avant le Gloria. Les appels de ceux qui demandaient miséricorde au Christ dans l'Évangile montrent la foi et le besoin avec lesquels nous pouvons faire nôtre cette prière. [Rite de 1962](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Écriture](https://www.newadvent.org/bible/mat020.htm)."}}],"canon":null,"biblicalScenes":["SH02"],"scripture":["Matthew 20:30–31"],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"}],"special":[]},{"id":"AO.CARD.003","title":"Gloria","studies":[{"id":"MM-PRIMARY-MB05","short":{"en":"The Gloria joins the angels' praise at Bethlehem to the Church's adoration of the Trinity. [Scripture](https://www.newadvent.org/bible/luk002.htm).","fr":"Le Gloria unit la louange des anges à Bethléem à l'adoration de la Sainte Trinité par l'Église. [Écriture](https://www.newadvent.org/bible/luk002.htm)."},"deep":{"en":"At the Saviour's birth, the angels proclaim God's glory and the peace brought to mankind (Luke 2:14). The Gloria takes up their acclamation and unfolds it into a hymn of praise: the Church blesses the Father, adores the Son, confesses him as the Lamb who takes away the world's sins, and glorifies the Holy Spirit. Its opening adapts Luke's account; the remainder develops that praise in the Church's own hymn. [Scripture](https://www.newadvent.org/bible/luk002.htm) · [Original 1962 Roman Missal page](https://gregobase.selapa.net/sources/42/300.png).","fr":"À la naissance du Sauveur, les anges annoncent la gloire de Dieu et la paix apportée aux hommes (Lc 2,14). Le Gloria reprend leur acclamation et la déploie en une grande hymne de louange : l’Église bénit le Père, adore le Fils, le reconnaît comme l’Agneau de Dieu qui enlève les péchés du monde et glorifie le Saint-Esprit. Le début du texte liturgique est adapté du récit de saint Luc ; le reste de l’hymne développe cette louange. [Écriture](https://www.newadvent.org/bible/luk002.htm) · [Missel romain de 1962, page originale](https://gregobase.selapa.net/sources/42/300.png)."}}],"canon":null,"biblicalScenes":["SH14"],"scripture":["Luke 2:14"],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"}],"special":["GLORIA_ONLY_WHEN_PRESCRIBED"]},{"id":"AO.CARD.004","title":"Collect","studies":[{"id":"MM-NEW-02","short":{"en":"One prayer of the Church [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"Une seule prière de l'Église [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."},"deep":{"en":"In the Collect, the priest gathers the Church's petitions into the appointed public prayer of the day. Its words are determined by the Mass being celebrated, sometimes with permitted commemorations. The faithful make this prayer their own through attentive prayer and the response Amen; a general explanation must never substitute a different day's text. [1962 rite](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"Dans la Collecte, le prêtre rassemble les demandes de l'Église dans la prière publique propre à la célébration. Ses paroles dépendent de la Messe du jour et, lorsque les rubriques le permettent, des commémoraisons. Les fidèles s'y unissent et la ratifient par l'Amen ; une explication générale ne remplace jamais le texte du jour. [Rite de 1962](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."}}],"canon":null,"biblicalScenes":[],"scripture":[],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"}],"special":[]},{"id":"AO.CARD.005","title":"Epistle / Lesson","studies":[{"id":"MM-NEW-03","short":{"en":"God addresses his Church [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"Dieu s'adresse à son Église [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."},"deep":{"en":"The Lesson or Epistle is not simply preparation for a sermon: it places the words of inspired Scripture within the Church's worship. The passage depends on the chosen Proper and may be one of several lessons on certain days. Listen for what God says through the text actually proclaimed, rather than assuming a fixed biblical episode at every Mass. [1962 rite](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Scripture](https://www.newadvent.org/bible/1co012.htm).","fr":"La Leçon ou l'Épître ne sert pas seulement d'introduction à l'homélie : la Parole inspirée de Dieu prend place dans le culte de l'Église. Le passage dépend du Propre choisi et certains jours comportent plusieurs leçons. Il faut écouter l'Écriture réellement proclamée, sans supposer que le même épisode se trouve à toutes les Messes. [Rite de 1962](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Écriture](https://www.newadvent.org/bible/1co012.htm)."}}],"canon":null,"biblicalScenes":[],"scripture":[],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"}],"special":["VARIABLE_LESSON_DO_NOT_SUBSTITUTE_EXAMPLE_FOR_SELECTED_PROPER"]},{"id":"AO.CARD.006","title":"Gradual · Alleluia / Tract / Sequence","studies":[{"id":"MM-NEW-04","short":{"en":"The psalmody between readings [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"La psalmodie entre les lectures [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."},"deep":{"en":"The Gradual, Alleluia, Tract or Sequence gives a sung response to God's word. Which chant occurs depends upon the liturgical calendar and the particular Mass: an Alleluia is not simply interchangeable with a Tract or Sequence. Its words deserve explanation from the actual Proper rather than an invented universal Scripture quotation. [1962 rite](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"Le Graduel, l'Alléluia, le Trait ou la Séquence répond en chant à la Parole de Dieu. Le choix dépend du calendrier et de la Messe célébrée : un Alléluia ne se substitue pas librement au Trait ou à la Séquence. Le sens des paroles doit être étudié à partir du Propre réellement assigné, sans inventer une citation biblique universelle. [Rite de 1962](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."}}],"canon":null,"biblicalScenes":[],"scripture":[],"authorLinks":[],"special":["PROPER_AND_SEASON_SPECIFIC_CHANT_OWNER"]},{"id":"AO.CARD.007","title":"Holy Gospel","studies":[{"id":"MM-PRIMARY-N01","short":{"en":"Munda cor meum recalls the purification of Isaiah's lips before the Gospel. [Scripture](https://www.newadvent.org/bible/isa006.htm).","fr":"Le Munda cor meum rappelle la purification des lèvres d'Isaïe avant l'Évangile. [Écriture](https://www.newadvent.org/bible/isa006.htm)."},"deep":{"en":"Before the Gospel, the minister who is to proclaim it prays “Munda cor meum ac labia mea.” He asks God to purify his heart and lips, just as Isaiah's lips were cleansed by the burning coal brought by a seraph (Isaiah 6:5–7). The vision teaches that one who proclaims God's word must first receive purification. At Mass this prayer prepares the priest or deacon to announce the Gospel worthily. [Scripture](https://www.newadvent.org/bible/isa006.htm) · [Original 1962 Roman Missal page](https://gregobase.selapa.net/sources/42/301.png).","fr":"Avant l’Évangile, le ministre qui doit le proclamer prie : « Munda cor meum ac labia mea ». Il demande à Dieu de purifier son cœur et ses lèvres, comme celles du prophète Isaïe furent purifiées par le charbon ardent apporté par un séraphin (Is 6,5–7). La vision biblique manifeste que celui qui annonce la parole de Dieu doit d’abord recevoir sa purification. À la Messe, la prière prépare le prêtre ou le diacre à proclamer dignement l’Évangile. [Écriture](https://www.newadvent.org/bible/isa006.htm) · [Missel romain de 1962, page originale](https://gregobase.selapa.net/sources/42/301.png)."}}],"canon":null,"biblicalScenes":[],"scripture":[],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"},{"title":"Lanslots · Illustrated Explanation (1897)","url":"https://archive.org/stream/illustratedexpla00lans/illustratedexpla00lans_djvu.txt"}],"special":["VARIABLE_GOSPEL_AND_LITURGICAL_FORM_CHECK"]},{"id":"AO.CARD.008","title":"Sermon / Homily","studies":[{"id":"MM-NEW-05","short":{"en":"The homily explains, it does not replace [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"L'homélie explique sans remplacer [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."},"deep":{"en":"The sermon may expound the readings, the feast, the doctrine or the Christian life, but it is not a fixed text of the Missal. The Church's worship and the homily therefore require distinct kinds of attention: the prescribed Mass texts retain their own identity even when preaching is brief, absent or extended. Any biblical links from a sermon should belong to that actual sermon, not to an imaginary standard reading. [1962 rite](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"Le sermon peut expliquer les lectures, la fête, la doctrine ou la vie chrétienne, mais il n'est pas un texte fixe du Missel. La liturgie et la prédication appellent donc une attention distincte : les textes prescrits de la Messe gardent leur identité, que le sermon soit bref, absent ou développé. Les références bibliques d'une homélie appartiennent à cette homélie réelle, non à une lecture standard imaginée. [Rite de 1962](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."}}],"canon":null,"biblicalScenes":[],"scripture":[],"authorLinks":[],"special":["HOMILY_CONTENT_NOT_FIXED_IN_THE_MISSAL"]},{"id":"AO.CARD.009","title":"Credo","studies":[{"id":"MM-PRIMARY-MB08","short":{"en":"At the Incarnation in the Creed, we profess that the eternal Word truly became man. [Scripture](https://www.newadvent.org/bible/joh001.htm).","fr":"À l'Incarnation proclamée dans le Credo, nous confessons que le Verbe éternel s'est vraiment fait homme. [Écriture](https://www.newadvent.org/bible/joh001.htm)."},"deep":{"en":"At “Et incarnatus est,” the Creed confesses that the eternal Son of God took a true human nature without ceasing to be God. St John expresses this mystery with the words, “The Word was made flesh” (John 1:14). The prescribed genuflection gives visible expression to adoration of the Incarnation. The Creed thus joins the profession of faith to a bodily act of reverence. [Scripture](https://www.newadvent.org/bible/joh001.htm) · [Original 1962 Roman Missal page](https://gregobase.selapa.net/sources/42/302.png).","fr":"Lorsque le Credo proclame « Et incarnatus est », l’Église confesse que le Fils éternel de Dieu a pris une véritable nature humaine, sans cesser d’être Dieu. Saint Jean résume ce mystère : « Le Verbe s’est fait chair » (Jn 1,14). La génuflexion prescrite à ces paroles rend visible l’adoration du mystère de l’Incarnation. La Messe demande ainsi que l’intelligence de la foi et l’attitude du corps s’accordent dans la profession du Credo. [Écriture](https://www.newadvent.org/bible/joh001.htm) · [Missel romain de 1962, page originale](https://gregobase.selapa.net/sources/42/302.png)."}}],"canon":null,"biblicalScenes":["SH13"],"scripture":["John 1:14"],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"}],"special":["CREDO_ONLY_WHEN_PRESCRIBED"]},{"id":"AO.CARD.010","title":"Offertory","studies":[{"id":"MM-PRIMARY-MB09","short":{"en":"The Lavabo's Psalm joins the priest's washing to a prayer for purity of heart. [Scripture](https://www.newadvent.org/bible/psa025.htm).","fr":"Le psaume du Lavabo unit l'ablution du prêtre à la demande de pureté du cœur. [Écriture](https://www.newadvent.org/bible/psa025.htm)."},"deep":{"en":"As the priest washes his hands at the Offertory, he prays Vulgate Psalm 25: “Lavabo inter innocentes manus meas.” The psalmist loves the Lord's dwelling and longs to remain among those who give him praise. In the Mass, the bodily washing accompanies the desire for purity of soul before the Eucharistic sacrifice. These are actual psalm verses, generally numbered Psalm 26 in modern Bibles. [Scripture](https://www.newadvent.org/bible/psa025.htm) · [Original 1962 Roman Missal page](https://gregobase.selapa.net/sources/42/303.png).","fr":"En se lavant les mains à l’Offertoire, le prêtre récite le psaume 25 de la Vulgate : « Lavabo inter innocentes manus meas ». Le psalmiste aime la maison du Seigneur et demande à demeurer parmi ceux qui rendent gloire à Dieu. Dans la Messe, le lavage matériel accompagne le désir d’une âme pure avant de s’approcher du sacrifice eucharistique. Les paroles sont bien celles du psaume, dont la numérotation moderne est généralement 26. [Écriture](https://www.newadvent.org/bible/psa025.htm) · [Missel romain de 1962, page originale](https://gregobase.selapa.net/sources/42/303.png)."}},{"id":"MM-PRIMARY-N03","short":{"en":"In spiritu humilitatis makes the Offertory an appeal for humble, contrite hearts. [Scripture](https://www.newadvent.org/bible/dan003.htm).","fr":"L'In spiritu humilitatis fait de l'Offertoire une supplication de cœurs humbles et contrits. [Écriture](https://www.newadvent.org/bible/dan003.htm)."},"deep":{"en":"After offering the chalice, the priest bows and prays “In spiritu humilitatis.” The words come from Azariah's plea in the furnace: deprived of the Temple's place and means of sacrifice, he asks God to receive a humble spirit and contrite heart (Daniel 3:38–40). The Mass takes up this disposition of humility before the Eucharistic sacrifice, whose worth comes from Christ himself. [Scripture](https://www.newadvent.org/bible/dan003.htm) · [Original 1962 Roman Missal page](https://gregobase.selapa.net/sources/42/303.png).","fr":"Après l’offrande du calice, le prêtre s’incline et prie « In spiritu humilitatis ». Ces paroles viennent de la supplication d’Azarias dans la fournaise : le peuple ne possède plus alors le lieu ni les moyens d’offrir les sacrifices du Temple, mais il demande à Dieu d’accueillir un esprit humilié et un cœur contrit (Dn 3,38–40). La Messe reprend cette humble disposition du cœur au seuil du sacrifice eucharistique, qui trouve sa valeur dans le Christ lui-même. [Écriture](https://www.newadvent.org/bible/dan003.htm) · [Missel romain de 1962, page originale](https://gregobase.selapa.net/sources/42/303.png)."}},{"id":"MM-PRIMARY-N04","short":{"en":"At Masses with Offertory incensation, Psalm 140 compares rising incense to prayer. [Scripture](https://www.newadvent.org/bible/psa140.htm).","fr":"Lorsque l'Offertoire comporte l'encensement, le psaume 140 compare l'encens qui monte à la prière. [Écriture](https://www.newadvent.org/bible/psa140.htm)."},"deep":{"en":"At the Offertory of Masses where incensation is prescribed, the priest prays with Vulgate Psalm 140: “Let my prayer rise before you like incense” (Psalm 140:2). The ascending smoke gives visible expression to the Church's desire that her prayers be received by God. Revelation also depicts incense joined to the prayers of the saints in heavenly worship (Revelation 8:3–4). This incensation depends on the form of Mass and is not part of the ordinary Low Mass. [Scripture](https://www.newadvent.org/bible/psa140.htm) · [Original 1962 Roman Missal page](https://gregobase.selapa.net/sources/42/303.png). [Second biblical passage](https://www.newadvent.org/bible/apo008.htm).","fr":"À l’Offertoire des Messes où l’encensement est prescrit, le prêtre prie avec le psaume 140 de la Vulgate : « Que ma prière s’élève devant vous comme l’encens » (Ps 140,2). La fumée qui monte rend visible le désir que les prières de l’Église soient reçues par Dieu. L’Apocalypse décrit également l’encens uni aux prières des saints dans le culte céleste (Ap 8,3–4). Cet encensement dépend du rite célébré et n’appartient pas à la Messe basse ordinaire. [Écriture](https://www.newadvent.org/bible/psa140.htm) · [Missel romain de 1962, page originale](https://gregobase.selapa.net/sources/42/303.png). [Deuxième passage biblique](https://www.newadvent.org/bible/apo008.htm)."}}],"canon":null,"biblicalScenes":["SH04","SH09","SH19"],"scripture":[],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"},{"title":"Lanslots · Illustrated Explanation (1897)","url":"https://archive.org/stream/illustratedexpla00lans/illustratedexpla00lans_djvu.txt"}],"special":[]},{"id":"AO.CARD.011","title":"Orate fratres & Secret","studies":[{"id":"MM-NEW-06","short":{"en":"My sacrifice and yours [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"Mon sacrifice et le vôtre [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."},"deep":{"en":"At Orate fratres the celebrant asks the brethren to pray that his sacrifice, also theirs in their proper way, may be acceptable to God. This distinction is important: the baptized unite their prayer, thanksgiving, sufferings and self-offering to the Eucharistic Sacrifice, while the ordained priest performs its sacramental action in the person of Christ. The Secret continues the petition over the prepared offerings and is proper to the celebration. [1962 ceremonial witness](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Scripture](https://www.newadvent.org/bible/rom012.htm) · [Pius XII, Mediator Dei §§82, 85–93](https://www.vatican.va/content/pius-xii/en/encyclicals/documents/hf_p-xii_enc_20111947_mediator-dei.html).","fr":"À l'Orate fratres, le célébrant demande aux fidèles de prier pour que son sacrifice, auquel ils s'unissent à leur manière, soit agréable à Dieu. La distinction importe : les baptisés joignent leur prière, leur action de grâces, leurs souffrances et leur propre offrande au Sacrifice eucharistique, tandis que le prêtre ordonné en accomplit l'action sacramentelle dans la personne du Christ. La Secrète poursuit la supplication sur les oblats et dépend de la célébration. [Témoin cérémoniel de 1962](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Écriture](https://www.newadvent.org/bible/rom012.htm) · [Pie XII, Mediator Dei §§82, 85–93](https://www.vatican.va/content/pius-xii/en/encyclicals/documents/hf_p-xii_enc_20111947_mediator-dei.html)."}}],"canon":null,"biblicalScenes":["SH09","SH12","SH20"],"scripture":["Romans 12:1"],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"}],"special":[]},{"id":"AO.CARD.012","title":"Preface","studies":[{"id":"MM-NEW-07","short":{"en":"Lift up your hearts [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"Élevons notre cœur [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."},"deep":{"en":"The dialogue Sursum corda calls the congregation to turn its attention to the Lord. The Preface then gives the Church's solemn thanksgiving, recalling the divine mysteries according to the text prescribed for this Mass. It opens into the Sanctus; the spiritual meaning is the united praise of God, not a fixed text that can be assigned regardless of feast or season. [1962 rite](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"Le dialogue Sursum corda invite l'assemblée à tourner son cœur vers le Seigneur. La Préface exprime ensuite l'action de grâces solennelle de l'Église en célébrant les mystères divins selon le texte prescrit pour cette Messe. Elle débouche sur le Sanctus ; son sens spirituel est la louange commune, non un texte fixe valable sans égard à la fête ou au temps liturgique. [Rite de 1962](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."}}],"canon":null,"biblicalScenes":["SH01"],"scripture":[],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"}],"special":["PREFACE_VARIABLE_SOURCE_GATED"]},{"id":"AO.CARD.013","title":"Sanctus · Benedictus","studies":[{"id":"MM-PRIMARY-MB11","short":{"en":"The Sanctus unites earthly worship with the praise heard by Isaiah and John. [Scripture](https://www.newadvent.org/bible/isa006.htm).","fr":"Le Sanctus unit le culte terrestre à la louange entendue par Isaïe et saint Jean. [Écriture](https://www.newadvent.org/bible/isa006.htm)."},"deep":{"en":"In a vision, Isaiah hears the seraphim proclaim the Lord's holiness three times (Isaiah 6:3). The Sanctus brings that praise into the Church's worship: heaven and earth are full of God's glory. Revelation describes heavenly beings likewise praising the divine holiness without ceasing (Revelation 4:8). These are distinct visions that illuminate the same adoration. The Mass says “Deus Sabaoth,” where the Clementine Isaiah text has “Deus exercituum.” [Scripture](https://www.newadvent.org/bible/isa006.htm) · [Original 1962 Roman Missal page](https://gregobase.selapa.net/sources/42/376.png). [Second biblical passage](https://www.newadvent.org/bible/apo004.htm).","fr":"Dans une vision, Isaïe entend les séraphins proclamer trois fois la sainteté du Seigneur (Is 6,3). Le Sanctus fait entrer cette louange dans la prière de l’Église : le ciel et la terre sont remplis de la gloire de Dieu. L’Apocalypse décrit elle aussi des êtres célestes célébrant sans cesse la sainteté divine (Ap 4,8). Ces deux visions distinctes éclairent la même adoration ; la formule de la Messe emploie « Deus Sabaoth », là où la Vulgate d’Isaïe dit « Deus exercituum ». [Écriture](https://www.newadvent.org/bible/isa006.htm) · [Missel romain de 1962, page originale](https://gregobase.selapa.net/sources/42/376.png). [Deuxième passage biblique](https://www.newadvent.org/bible/apo004.htm)."}}],"canon":null,"biblicalScenes":["SH10","SH17","SH24"],"scripture":["Isaiah 6:3","Matthew 21:9"],"authorLinks":[{"title":"Lanslots · Illustrated Explanation (1897)","url":"https://archive.org/stream/illustratedexpla00lans/illustratedexpla00lans_djvu.txt"}],"special":[]},{"id":"AO.CANON.01","title":"Te igitur","studies":[{"id":"MM-NEW-08","short":{"en":"The whole Church in Te igitur [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"Toute l'Église dans le Te igitur [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."},"deep":{"en":"The opening petition of the Roman Canon seeks God's acceptance of the offering and peace, protection and unity for the Church. Naming the Pope and the local bishop expresses the ecclesial dimension of the sacrifice, not merely a list of private intentions. The priest prays at the altar while the faithful can unite their own prayers to his intercession; do not confuse his silent words with an obligatory congregational recitation. [1962 rite](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Scripture](https://www.newadvent.org/bible/1ti002.htm).","fr":"La première supplication du Canon romain demande à Dieu d'agréer l'offrande et de donner à l'Église la paix, la protection et l'unité. La mention du Pape et de l'évêque du lieu exprime la dimension ecclésiale du Sacrifice, non une simple liste d'intentions privées. Tandis que le prêtre prie à l'autel, les fidèles peuvent unir leur prière à son intercession sans devoir réciter chaque parole silencieuse. [Rite de 1962](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Écriture](https://www.newadvent.org/bible/1ti002.htm)."}}],"canon":{"question":"If Christ's sacrifice is complete and infinitely acceptable, why does the priest first ask the Father to accept the offering?","text":"The prayer addresses the Father through Christ, placing the sacrifice within the Church's visible communion. Guéranger reads its supplication as ecclesial action even while the celebrant speaks quietly. The mention of the Pope and appropriate bishop expresses communion; it is not merely administrative information added to a private devotion. The question of acceptance will return after the Consecration in Supra quae, but here the Canon is already concerned with the Church's peace, protection and unity.","transition":"The sacred action belongs to Christ and His Church; silence of voice does not privatize the sacrifice.","sources":{"guérangerOriginalFrench":["FRG18"],"stAlphonsusOriginalPrinted":[],"otherOriginalAuthorCritical":[],"inheritedBilingualManuscripts":["MM-NEW-08"]}},"biblicalScenes":["SH12","SH23"],"scripture":["1 Timothy 2:1–2"],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"},{"title":"Lanslots · Illustrated Explanation (1897)","url":"https://archive.org/stream/illustratedexpla00lans/illustratedexpla00lans_djvu.txt"}],"special":[]},{"id":"AO.CANON.02","title":"Memento, Domine — Living","studies":[{"id":"MM-NEW-09","short":{"en":"Remembering the living [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"Se souvenir des vivants [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."},"deep":{"en":"In the Memento for the living, the Canon embraces particular persons and those who stand near the altar, whose faith and devotion are named in the prayer. This is a fitting moment to place one's family, benefactors and those in need before God. Their union with the offering is real, but it does not give them the ministerial priest's power to consecrate. [1962 rite](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Guéranger](https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/).","fr":"Dans le Mémento des vivants, le Canon englobe des personnes particulières et ceux qui entourent l'autel, dont la foi et la dévotion sont évoquées. C'est un moment approprié pour présenter à Dieu sa famille, ses bienfaiteurs et ceux qui sont dans le besoin. Leur union à l'offrande est réelle, mais ne leur confère pas le pouvoir de consacrer propre au prêtre ordonné. [Rite de 1962](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Guéranger](https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/)."}}],"canon":{"question":"Whose sacrifice is this, and how can individual intentions belong to a single public offering?","text":"The Memento brings particular persons before the Father and expressly names the faith and devotion of those around the altar. Guéranger's treatment notes how intercession extends to the circumstantes. The faithful's participation must be understood without confusing their spiritual union to the offering with the celebrant's power of sacramental Consecration. Private intentions enter the public liturgical prayer without turning the Canon into a collection of private liturgies.","transition":"The passage from named persons to the company of saints prepares the next prayer, Communicantes.","sources":{"guérangerOriginalFrench":["FRG19","FRG31"],"stAlphonsusOriginalPrinted":[],"otherOriginalAuthorCritical":[],"inheritedBilingualManuscripts":["MM-NEW-09"]}},"biblicalScenes":[],"scripture":[],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"}],"special":[]},{"id":"AO.CANON.03","title":"Communicantes","studies":[{"id":"MM-NEW-10","short":{"en":"The communion of the saints [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"La communion des saints [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."},"deep":{"en":"Communicantes invokes communion with the Blessed Virgin Mary, St Joseph, the apostles and the martyrs. The Church praying on earth does not offer this sacrifice in isolation from the saints in glory. Earlier explanations that omit St Joseph describe a historical text state: his name was inserted into the Roman Canon by decree effective on 8 December 1962 and must be retained even when a special Communicantes formula is appointed in the corresponding 1962 rite. [1962 rite](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Guéranger](https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/) · [Scripture](https://www.icrsp.org/Pages/mois-saint-joseph.php?groupe=magistere&nom=decret). [Original 1962 decree in French translation](https://www.icrsp.org/Pages/mois-saint-joseph.php?groupe=magistere&nom=decret).","fr":"Le Communicantes invoque la communion avec la bienheureuse Vierge Marie, saint Joseph, les apôtres et les martyrs. L'Église qui prie sur la terre n'offre pas ce Sacrifice séparément des saints dans la gloire. Les explications anciennes qui omettent saint Joseph décrivent un état antérieur du texte : son nom fut inséré au Canon romain par un décret entré en vigueur le 8 décembre 1962 et doit être conservé même lorsque la Messe prescrit une formule propre du Communicantes. [Rite de 1962](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Guéranger](https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/) · [Écriture](https://www.icrsp.org/Pages/mois-saint-joseph.php?groupe=magistere&nom=decret). [Décret du 13 novembre 1962](https://www.icrsp.org/Pages/mois-saint-joseph.php?groupe=magistere&nom=decret)."}}],"canon":{"question":"Why name the saints within a sacrificial prayer addressed to the Father?","text":"Communicantes professes the Church's communion with Mary, Joseph, the apostles and martyrs; the faithful on earth are not a separate worshipping body from the saints in glory. Guéranger wrote before Joseph's insertion into the Roman Canon, and Lanslots's 1897 transcription likewise omits him. Both witnesses are valuable for historical comparison but cannot be presented as the wording of the liturgy after the 1962 insertion became effective. The Church's present text controls, while the history explains what changed.","transition":"The Canon turns from those for whom the Church intercedes to the disposition of the offering now before God.","sources":{"guérangerOriginalFrench":["FRG32","FRG33"],"stAlphonsusOriginalPrinted":[],"otherOriginalAuthorCritical":["L1897-DISC-10"],"inheritedBilingualManuscripts":["MM-NEW-10"]}},"biblicalScenes":["SH23"],"scripture":[],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"},{"title":"Lanslots · Illustrated Explanation (1897)","url":"https://archive.org/stream/illustratedexpla00lans/illustratedexpla00lans_djvu.txt"}],"special":["ST_JOSEPH_INSERTION_EFFECTIVE_1962_12_08"]},{"id":"AO.CANON.04","title":"Hanc igitur","studies":[{"id":"MM-NEW-11","short":{"en":"This oblation and our deliverance [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"Cette oblation et notre délivrance [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."},"deep":{"en":"In Hanc igitur the celebrant asks God graciously to receive the offering and to order our days in peace, rescue us from eternal condemnation and admit us among the elect. The extended hands are a gesture prescribed by the Roman rite; similarities to Old Testament laying-on of hands may illuminate their meaning but do not prove the historical origin of the Christian gesture. [1962 rite](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Guéranger](https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/) · [Scripture](https://www.newadvent.org/bible/lev008.htm).","fr":"Dans le Hanc igitur, le célébrant demande à Dieu d'accueillir l'offrande avec bienveillance, de disposer nos jours dans la paix, de nous délivrer de la damnation et de nous compter parmi les élus. Les mains étendues constituent un geste prescrit par le rite romain ; l'analogie avec l'imposition des mains de l'Ancien Testament en éclaire le sens sans démontrer l'origine historique du geste chrétien. [Rite de 1962](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Guéranger](https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/) · [Écriture](https://www.newadvent.org/bible/lev008.htm)."}}],"canon":{"question":"What do the priest's extended hands mean, and is the gesture derived from an Old Testament sacrificial act?","text":"The prayer petitions acceptance, peace, deliverance from eternal condemnation and admission among the elect. Guéranger, St Alphonsus and Lanslots associate the extended hands with biblical imposition upon a victim. That is a meaningful traditional comparison, not proof that this Roman gesture originated by reenacting Leviticus. Leviticus 8:14 discusses hands upon the sin-offering bullock; Leviticus 16 also distinguishes the slain goat from the live scapegoat sent away. Torma's recent conflation requires correction rather than repetition.","transition":"The petition for an acceptable offering narrows into a prayer for the offering's transformation at Quam oblationem.","sources":{"guérangerOriginalFrench":["FRG20","FRG34"],"stAlphonsusOriginalPrinted":["ALPX17"],"otherOriginalAuthorCritical":["L1897-DISC-06","TORMA-01"],"inheritedBilingualManuscripts":["MM-NEW-11"]}},"biblicalScenes":["SH09","SH19"],"scripture":[],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"},{"title":"Lanslots · Illustrated Explanation (1897)","url":"https://archive.org/stream/illustratedexpla00lans/illustratedexpla00lans_djvu.txt"}],"special":[]},{"id":"AO.CANON.05","title":"Quam oblationem","studies":[{"id":"MM-NEW-12","short":{"en":"The offering prepared for the mystery [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"L'offrande préparée au mystère [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."},"deep":{"en":"In Quam oblationem the priest asks God to make the offering blessed, approved, confirmed, reasonable and acceptable, so that it may become for us the Body and Blood of Christ. Under the 1962 ceremonial directions, he makes three signs of the Cross over both offerings, one over the Host at Corpus, and one over the chalice at Sanguis. These five signs precede, and are not themselves, the separate sacramental consecrations of bread and wine. [Roman Canon text and rubrics](https://en.wikipedia.org/wiki/Text_and_rubrics_of_the_Roman_Canon) · [O’Connell, The Celebration of Mass (1962), p. 262](https://isidore.co/misc/Res%20pro%20Deo/ITOPL_OCR-layer-only/11a.%20Liturgy/d-The%20Celebration%20of%20Mass-%20O%27Connel%201962_OCR.pdf).","fr":"Dans Quam oblationem, le prêtre demande à Dieu de rendre l’offrande bénie, agréée, ratifiée, raisonnable et acceptable, afin qu’elle devienne pour nous le Corps et le Sang du Christ. Selon les prescriptions cérémonielles de 1962, il trace trois signes de croix sur les deux oblats, puis un sur l’Hostie au mot Corpus et un sur le calice au mot Sanguis. Ces cinq signes précèdent les consécrations sacramentelles distinctes du pain et du vin : ils ne constituent pas eux-mêmes ces consécrations. [Texte et rubriques du Canon romain](https://en.wikipedia.org/wiki/Text_and_rubrics_of_the_Roman_Canon) · [O’Connell, The Celebration of Mass (1962), p. 262](https://isidore.co/misc/Res%20pro%20Deo/ITOPL_OCR-layer-only/11a.%20Liturgy/d-The%20Celebration%20of%20Mass-%20O%27Connel%201962_OCR.pdf)."}}],"canon":{"question":"Why does the Church ask God to make the offering 'reasonable' and acceptable immediately before Consecration?","text":"Guéranger relates rationabilem to the spiritual worship enjoined in Romans 12:1. The prayer asks that the oblation become for us Christ's Body and Blood. The five pre-Consecration crosses emphasize the actual Latin petitions but do not cause transubstantiation by themselves. Torma's description of the signs can be compared with the 1962 text; speculative interpretations of the five wounds are distinct from their rubrical timing and historical origin.","transition":"The act prayed for is about to occur at Christ's own words, not at the preceding crosses.","sources":{"guérangerOriginalFrench":["FRG21","FRG35","FRG36","FRG37"],"stAlphonsusOriginalPrinted":[],"otherOriginalAuthorCritical":["TORMA-02"],"inheritedBilingualManuscripts":["MM-NEW-12"]}},"biblicalScenes":[],"scripture":[],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"}],"special":[]},{"id":"AO.CANON.06","title":"Consecration of the Sacred Host","studies":[{"id":"MM-PRIMARY-MB14","short":{"en":"At the words over the Host, Christ becomes truly present under the appearance of bread. [Scripture](https://www.newadvent.org/bible/1co011.htm).","fr":"Aux paroles sur l'Hostie, le Christ devient réellement présent sous l'apparence du pain. [Écriture](https://www.newadvent.org/bible/1co011.htm)."},"deep":{"en":"At the Last Supper Jesus takes bread and declares, “This is my body,” commanding the apostles to do this in remembrance of him (1 Corinthians 11:23–24). At the heart of Mass the priest speaks the words of consecration in the person of Christ, and the bread truly becomes his Body. Calvary's sacrifice, offered once in history, is made sacramentally present rather than begun again as another historical event. The 1962 Roman formula has its own received liturgical wording. [Scripture](https://www.newadvent.org/bible/1co011.htm) · [Original 1962 Roman Missal page](https://gregobase.selapa.net/sources/42/388.png). [Doctrinal or patristic source](https://www.newadvent.org/summa/4083.htm).","fr":"À la Cène, Jésus prend le pain et déclare : « Ceci est mon Corps », en ordonnant aux Apôtres de faire cela en mémoire de lui (1 Co 11,23–24). Au cœur de la Messe, le prêtre prononce les paroles de la consécration en la personne du Christ : le pain devient véritablement son Corps. Le sacrifice du Calvaire, offert une fois dans l’histoire, est rendu sacramentellement présent, non recommencé comme un nouvel événement. Le texte romain de 1962 possède sa formulation liturgique propre. [Écriture](https://www.newadvent.org/bible/1co011.htm) · [Missel romain de 1962, page originale](https://gregobase.selapa.net/sources/42/388.png). [Commentaire doctrinal ou patristique](https://www.newadvent.org/summa/4083.htm)."}}],"canon":{"question":"At which instant is Christ truly present, and why are there several actions before and after it?","text":"The institution narrative recalls the Last Supper, but the received Roman words and gestures are a liturgical text with history, not a verbatim transcript from one Evangelist. Guéranger comments on details such as Christ lifting His eyes. The Real Presence follows from the words of Consecration: the priest's immediate genuflection acknowledges what has already occurred. The elevation displays the consecrated Host for adoration; it does not make the bread become Christ's Body. Claims that every accompanying detail originates from a particular early Pope need manuscript evidence.","transition":"The chalice Consecration completes the two-species sacramental sign of the one sacrifice.","sources":{"guérangerOriginalFrench":["FRG22","FRG38","FRG39"],"stAlphonsusOriginalPrinted":[],"otherOriginalAuthorCritical":["L1897-DISC-01","L1897-DISC-08"],"inheritedBilingualManuscripts":["MM-PRIMARY-MB14"]}},"biblicalScenes":["SH11","SH18","SH20"],"scripture":["1 Corinthians 11:23–26"],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"},{"title":"Lanslots · Illustrated Explanation (1897)","url":"https://archive.org/stream/illustratedexpla00lans/illustratedexpla00lans_djvu.txt"}],"special":["CONSECRATION_BREAD_NOT_COMBINED_WITH_CHALICE"]},{"id":"AO.CANON.07","title":"Consecration of the Chalice","studies":[{"id":"MM-PRIMARY-MB15","short":{"en":"At the words over the chalice, the Precious Blood becomes truly present under the appearance of wine. [Scripture](https://www.newadvent.org/bible/luk022.htm).","fr":"Aux paroles sur le calice, le Précieux Sang devient réellement présent sous l'apparence du vin. [Écriture](https://www.newadvent.org/bible/luk022.htm)."},"deep":{"en":"In giving the chalice to the apostles, Christ reveals that his Blood is poured out for the new covenant and the forgiveness of sins (Luke 22:20; Matthew 26:28). The consecration of the chalice directs the Church to Christ's redeeming self-offering and the real presence of his Precious Blood. In the 1962 Roman Canon the words “mysterium fidei” occur within the formula pronounced over the chalice, although they are not a verbatim phrase from Luke's institution account. [Scripture](https://www.newadvent.org/bible/luk022.htm) · [Original 1962 Roman Missal page](https://gregobase.selapa.net/sources/42/389.png). [Doctrinal or patristic source](https://www.newadvent.org/summa/4075.htm).","fr":"En donnant le calice aux Apôtres, le Christ révèle que son Sang est versé pour l’alliance nouvelle et la rémission des péchés (cf. Lc 22,20 ; Mt 26,28). À la consécration du calice, la Messe nous tourne vers l’offrande rédemptrice du Christ et la présence réelle de son Précieux Sang. Le Canon romain de 1962 inclut les mots « mysterium fidei » dans la formule prononcée sur le calice : ils appartiennent ici au texte liturgique reçu, sans être tirés mot pour mot du récit de saint Luc. [Écriture](https://www.newadvent.org/bible/luk022.htm) · [Missel romain de 1962, page originale](https://gregobase.selapa.net/sources/42/389.png). [Commentaire doctrinal ou patristique](https://www.newadvent.org/summa/4075.htm)."}}],"canon":{"question":"How does Christ's Blood of the covenant become present without a second historical shedding of blood?","text":"The Roman chalice formula relates the Blood of Christ to the new covenant and the forgiveness of sins. Its received 1962 wording includes mysterium fidei inside the consecratory formula. The Church's sacramental offering does not reproduce a second bloody death: the two species signify the sacrificial separation of Body and Blood while the whole risen Christ remains present under either species. Older commentators may offer symbolic explanations of cross-signs or narrative details, but no source may silently replace the 1962 formula with a harmonized Gospel paraphrase.","transition":"Once both Consecrations have occurred, the Canon explicitly names what the Church remembers and offers.","sources":{"guérangerOriginalFrench":["FRG22"],"stAlphonsusOriginalPrinted":[],"otherOriginalAuthorCritical":["L1897-DISC-01","L1897-DISC-08"],"inheritedBilingualManuscripts":["MM-PRIMARY-MB15"]}},"biblicalScenes":["SH06","SH08","SH11","SH18","SH20"],"scripture":["Luke 22:20"],"authorLinks":[{"title":"Lanslots · Illustrated Explanation (1897)","url":"https://archive.org/stream/illustratedexpla00lans/illustratedexpla00lans_djvu.txt"}],"special":["CONSECRATION_CHALICE_NOT_COMBINED_WITH_BREAD"]},{"id":"AO.CANON.08","title":"Unde et memores","studies":[{"id":"MM-PRIMARY-MB16","short":{"en":"Unde et memores offers the consecrated Victim while remembering the Passion, Resurrection and Ascension. [Scripture](https://www.newadvent.org/bible/1co011.htm).","fr":"L'Unde et memores offre la Victime consacrée en faisant mémoire de la Passion, de la Résurrection et de l'Ascension. [Écriture](https://www.newadvent.org/bible/1co011.htm)."},"deep":{"en":"After the Consecration, the Canon remembers the Lord's blessed Passion, Resurrection and Ascension. St Paul teaches that by eating this Bread and drinking this Chalice the faithful proclaim the Lord's death until he comes (1 Corinthians 11:26). “Unde et memores” gives this living remembrance a place in the Church's offering: the whole Paschal victory of Christ is confessed within the one Eucharistic sacrifice. [Scripture](https://www.newadvent.org/bible/1co011.htm) · [Original 1962 Roman Missal page](https://gregobase.selapa.net/sources/42/390.png). [Doctrinal or patristic source](https://la.wikisource.org/wiki/De_sacramentis_(Ambrosius)).","fr":"Après la consécration, le Canon proclame la mémoire de la Passion bienheureuse, de la Résurrection et de l’Ascension du Seigneur. Saint Paul enseigne qu’en mangeant ce Pain et en buvant ce Calice, les fidèles annoncent la mort du Seigneur jusqu’à ce qu’il vienne (1 Co 11,26). « Unde et memores » exprime cette mémoire vivante dans l’offrande de l’Église : toute la victoire pascale du Christ est confessée dans l’unique sacrifice eucharistique. [Écriture](https://www.newadvent.org/bible/1co011.htm) · [Missel romain de 1962, page originale](https://gregobase.selapa.net/sources/42/390.png). [Commentaire doctrinal ou patristique](https://la.wikisource.org/wiki/De_sacramentis_(Ambrosius))."}}],"canon":{"question":"Why remember Passion, Resurrection and Ascension within the sacrifice instead of stopping at Calvary?","text":"The prayer does not isolate a moment of death. It explicitly commemorates the saving mysteries of Christ crucified, risen and ascended, and offers the gifts received from God. Guéranger explains that the signs made after Consecration do not bless Christ as though He required further sanctification; they recall His saving sacrifice. This is where a salvation-history narrative can reach beyond the historical Passion, while the liturgical commentary explains an actual Roman prayer rather than assigning arbitrary events to each cross.","transition":"The Canon then invokes the sacrifices named in ancient Scripture, now after Christ's presence upon the altar.","sources":{"guérangerOriginalFrench":["FRG23","FRG40"],"stAlphonsusOriginalPrinted":[],"otherOriginalAuthorCritical":[],"inheritedBilingualManuscripts":["MM-PRIMARY-MB16"]}},"biblicalScenes":["SH18","SH20","SH21","SH22"],"scripture":["1 Corinthians 11:26"],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"}],"special":[]},{"id":"AO.CANON.09","title":"Supra quae","studies":[{"id":"MM-PRIMARY-MB17","short":{"en":"Abel's accepted offering is a biblical figure of sacrifice recalled in Supra quae. [Scripture](https://www.newadvent.org/bible/gen004.htm).","fr":"L'offrande agréée d'Abel est une figure biblique du sacrifice rappelée dans le Supra quae. [Écriture](https://www.newadvent.org/bible/gen004.htm)."},"deep":{"en":"In “Supra quae,” the priest asks God to receive the Church's offering as he received that of righteous Abel. Genesis relates that Abel brought the firstborn of his flock, and God looked favourably upon his offering (Genesis 4:4). The Canon recalls the righteousness of the giver and God's acceptance, while the Church confidently petitions for the sacrifice of Christ. Abel is a biblical person expressly named by the prayer, not an event restaged at the altar. [Scripture](https://www.newadvent.org/bible/gen004.htm) · [Original 1962 Roman Missal page](https://gregobase.selapa.net/sources/42/390.png).","fr":"Dans « Supra quae », le prêtre demande à Dieu d’accueillir l’offrande de l’Église comme il accueillit celle du juste Abel. Selon la Genèse, Abel apporta les premiers-nés de son troupeau et Dieu regarda favorablement son sacrifice (Gn 4,4). Le Canon rappelle la fidélité du juste et l’agrément divin, afin que l’Église supplie avec confiance pour le sacrifice du Christ. Abel est ici un personnage biblique explicitement nommé, non le protagoniste d’une cérémonie reproduite à l’autel. [Écriture](https://www.newadvent.org/bible/gen004.htm) · [Missel romain de 1962, page originale](https://gregobase.selapa.net/sources/42/390.png)."}},{"id":"MM-PRIMARY-MB18","short":{"en":"Abraham's willingness to offer Isaac foreshadows the Father's gift of the Son, without Isaac being slain. [Scripture](https://www.newadvent.org/bible/gen022.htm).","fr":"L'obéissance d'Abraham prêt à offrir Isaac préfigure le don du Fils, sans qu'Isaac ait été mis à mort. [Écriture](https://www.newadvent.org/bible/gen022.htm)."},"deep":{"en":"The Canon next recalls Abraham's sacrifice. God tests the patriarch's faith by asking for his beloved son Isaac, then stops Abraham before the child is killed (Genesis 22). Christian tradition sees in Abraham's obedience and intended offering a figure of the perfect self-gift accomplished in Christ. The Mass recalls a real episode of Genesis and understands it in the light of Jesus' redeeming sacrifice. [Scripture](https://www.newadvent.org/bible/gen022.htm) · [Original 1962 Roman Missal page](https://gregobase.selapa.net/sources/42/390.png). [Second biblical passage](https://www.newadvent.org/bible/heb011.htm).","fr":"Le Canon évoque ensuite le sacrifice d’Abraham. Dieu éprouve la foi du patriarche en lui demandant Isaac, son fils bien-aimé, puis arrête sa main avant que l’enfant soit immolé (Gn 22). La tradition chrétienne reconnaît dans cette obéissance et cette offrande annoncée une figure de l'offrande parfaite du Christ à son Père. La Messe rappelle donc un épisode réel de la Genèse, tout en l’éclairant par le sacrifice rédempteur de Jésus. [Écriture](https://www.newadvent.org/bible/gen022.htm) · [Missel romain de 1962, page originale](https://gregobase.selapa.net/sources/42/390.png). [Deuxième passage biblique](https://www.newadvent.org/bible/heb011.htm)."}},{"id":"MM-PRIMARY-MB19","short":{"en":"Melchisedech's bread and wine illuminate the Eucharistic sacrifice as a traditional biblical figure. [Scripture](https://www.newadvent.org/bible/gen014.htm).","fr":"Le pain et le vin de Melchisédech éclairent le Sacrifice eucharistique par une figure biblique traditionnelle. [Écriture](https://www.newadvent.org/bible/gen014.htm)."},"deep":{"en":"Melchizedek, king of Salem and priest of God Most High, brings out bread and wine and blesses Abram (Genesis 14:18–20). The Canon names him among the ancient figures of an offering pleasing to God. Hebrews explains how his priesthood sheds light on Christ's (Hebrews 7). Christian interpretation sees a Eucharistic foreshadowing in the bread and wine, although Genesis itself does not explicitly describe those elements being sacrificed. [Scripture](https://www.newadvent.org/bible/gen014.htm) · [Original 1962 Roman Missal page](https://gregobase.selapa.net/sources/42/391.png). [Hebrews 7](https://www.newadvent.org/bible/heb007.htm) · [Cyprian, Epistle 62](https://www.newadvent.org/fathers/050662.htm).","fr":"Melchisédech, roi de Salem et prêtre du Dieu Très-Haut, accueille Abram avec du pain et du vin et le bénit (Gn 14,18–20). Le Canon le nomme parmi les figures anciennes de l’offrande agréable à Dieu. L’épître aux Hébreux explique en outre pourquoi son sacerdoce éclaire celui du Christ (He 7). La lecture chrétienne voit dans le pain et le vin une préfiguration eucharistique ; le récit de la Genèse, pris seul, ne décrit pas explicitement leur immolation sacrificielle. [Écriture](https://www.newadvent.org/bible/gen014.htm) · [Missel romain de 1962, page originale](https://gregobase.selapa.net/sources/42/391.png). [Hébreux 7](https://www.newadvent.org/bible/heb007.htm) · [Cyprien, Lettre 62](https://www.newadvent.org/fathers/050662.htm)."}}],"canon":{"question":"Why ask that the Eucharistic offering be received like the gifts of Abel, Abraham and Melchisedech, if it is infinitely greater?","text":"Guéranger and Gihr confront this as a real theological problem rather than a decorative list of Old Testament stories. Gihr, drawing on St Thomas, locates the comparison in the faith and devotion of the earlier offerers and God's favourable regard, not in equality between victims. Abel's faith, Abraham's obedience and Melchisedech's priesthood are distinct interpretive avenues. Genesis says Melchisedech brought forth bread and wine; Gihr's assertion that he sacrificed them is subsequent Christian interpretation, not the Bible's direct narration. His hypothesis of fire consuming Abel's offering likewise exceeds Genesis 4.","transition":"The question of acceptance leads into the more difficult language of the angel, the heavenly altar and participation in heavenly blessing.","sources":{"guérangerOriginalFrench":["FRG41","FRG42","FRG43"],"stAlphonsusOriginalPrinted":["ALPX18"],"otherOriginalAuthorCritical":["GIHR-03","GIHR-04","GIHR-05","L1897-DISC-07"],"inheritedBilingualManuscripts":["MM-PRIMARY-MB17","MM-PRIMARY-MB18","MM-PRIMARY-MB19"]}},"biblicalScenes":["SH03","SH04","SH05"],"scripture":["Genesis 4:4","Genesis 22:1–19","Genesis 14:18–20","Hebrews 7:1–17"],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"},{"title":"Lanslots · Illustrated Explanation (1897)","url":"https://archive.org/stream/illustratedexpla00lans/illustratedexpla00lans_djvu.txt"}],"special":[]},{"id":"AO.CANON.10","title":"Supplices te rogamus","studies":[{"id":"MM-NEW-13","short":{"en":"The holy Angel and the heavenly altar [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"L'Ange saint et l'autel céleste [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."},"deep":{"en":"In Supplices te rogamus the priest asks that the offering be borne before God's majesty by the hands of his holy Angel, so that communicants may receive heavenly blessing and grace. St Thomas Aquinas explains both an angel presenting the prayers of priest and people and a spiritual interpretation referring to Christ, the Angel of great counsel. These are interpretations, not a dogmatic identification imposed by the prayer. Aquinas explicitly denies that the consecrated species or Christ's true Body are physically carried from the altar to heaven. [Roman Canon](https://en.wikipedia.org/wiki/Text_and_rubrics_of_the_Roman_Canon) · [St Thomas, Summa theologiae III, q. 83, a. 4, ad 9](https://www.newadvent.org/summa/4083.htm#article4) · [Guéranger](https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/).","fr":"Dans Supplices te rogamus, le prêtre demande que l'offrande soit portée devant la majesté divine par les mains du saint Ange de Dieu, afin que ceux qui communient reçoivent la bénédiction et la grâce célestes. Saint Thomas d'Aquin explique à la fois l'intervention d'un ange présentant les prières du prêtre et du peuple, et une interprétation spirituelle rapportant l'Ange au Christ, l'Ange du grand conseil. Il s'agit d'interprétations, non d'une identification dogmatique imposée par la prière. Saint Thomas exclut expressément que les espèces consacrées ou le vrai Corps du Christ soient matériellement transportés de l'autel au ciel. [Canon romain](https://en.wikipedia.org/wiki/Text_and_rubrics_of_the_Roman_Canon) · [Saint Thomas, Somme théologique III, q. 83, a. 4, ad 9](https://www.newadvent.org/summa/4083.htm#article4) · [Guéranger](https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/)."}}],"canon":{"question":"Who is the holy Angel, and what does it mean for the offering to be borne to the heavenly altar?","text":"Guéranger interprets the Angel christologically; Lanslots juxtaposes that account with other angelic readings and acknowledges uncertainty. St Alphonsus reports a Christological explanation from a French predecessor but favours the reading associated with St Thomas, concerning the angelic presentation of the Church's prayers. These are distinguishable authorial positions, not several synonyms. St Thomas expressly resists imagining that Christ's physical Body or the consecrated species leave the altar to be carried to heaven. The petition concerns heavenly communion and blessing, not Eucharistic relocation.","transition":"From worship joined to heaven, the Canon turns to those who have died in faith and await the fulfilment of the promises.","sources":{"guérangerOriginalFrench":["FRG44","FRG45"],"stAlphonsusOriginalPrinted":["ALPX19"],"otherOriginalAuthorCritical":["L1897-DISC-02"],"inheritedBilingualManuscripts":["MM-NEW-13"]}},"biblicalScenes":["SH22","SH24"],"scripture":[],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"},{"title":"Lanslots · Illustrated Explanation (1897)","url":"https://archive.org/stream/illustratedexpla00lans/illustratedexpla00lans_djvu.txt"}],"special":["SUPPLICES_ANGEL_IDENTITY_DISPUTED_NOT_DOGMA"]},{"id":"AO.CANON.11","title":"Memento etiam, Domine — Dead","studies":[{"id":"MM-NEW-14","short":{"en":"The faithful departed [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"Les fidèles défunts [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."},"deep":{"en":"The Memento for the dead prays for those who have gone before us in faith and rest in peace, asking God to grant light, refreshment and peace. To pray for the dead is an act of charity and hope in God's mercy, not an attempt to declare the final state of an individual soul. Historical rules about public naming in the Canon must be kept distinct from private intercession and from the normative rubrics of the particular celebration. [1962 rite](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Guéranger](https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/) · [Scripture](https://www.newadvent.org/bible/1th004.htm).","fr":"Le Mémento des défunts prie pour ceux qui nous ont précédés dans la foi et reposent dans la paix, afin que Dieu leur accorde la lumière, le rafraîchissement et la paix. Prier pour les morts est un acte de charité et d'espérance en la miséricorde divine, non une déclaration sur le sort éternel d'une âme particulière. Les anciennes règles sur les noms publiquement mentionnés au Canon se distinguent de la prière privée et des rubriques applicables. [Rite de 1962](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Guéranger](https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/) · [Écriture](https://www.newadvent.org/bible/1th004.htm)."}}],"canon":{"question":"What can the Eucharistic Sacrifice mean for those who have died, and how does naming them differ from private prayer?","text":"The Canon commends the faithful departed to God, asking for a place of refreshment, light and peace. Guéranger's interpretation of the signum fidei makes one historic link to Christian initiation; it should not displace the text's own wording. Lanslots distinguishes the rules and history of public liturgical naming from the possibility of private intercession. We should explain the Church's prayer for the dead without pretending the celebrant knows the final state of any particular soul or collapsing rubrical diptychs into the personal intentions of every attendee.","transition":"The prayer next includes the still-living sinners who beg to share the saints' company.","sources":{"guérangerOriginalFrench":["FRG46","FRG47"],"stAlphonsusOriginalPrinted":[],"otherOriginalAuthorCritical":["L1897-DISC-05"],"inheritedBilingualManuscripts":["MM-NEW-14"]}},"biblicalScenes":[],"scripture":[],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"},{"title":"Lanslots · Illustrated Explanation (1897)","url":"https://archive.org/stream/illustratedexpla00lans/illustratedexpla00lans_djvu.txt"}],"special":[]},{"id":"AO.CANON.12","title":"Nobis quoque peccatoribus","studies":[{"id":"MM-NEW-15","short":{"en":"Nobis quoque: the sinner's hope [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"Nobis quoque : l'espérance du pécheur [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."},"deep":{"en":"At Nobis quoque peccatoribus, the celebrant asks that sinners who hope in God's manifold mercies receive some part in fellowship with the apostles and martyrs. The petition is marked by humility: the promised reward is sought not by presuming on personal merit, but by asking pardon and admittance through Christ. It gives the faithful language for the hope of conversion during the silent Canon. [1962 rite](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Guéranger](https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/).","fr":"Au Nobis quoque peccatoribus, le célébrant demande que les pécheurs qui espèrent en la multitude des miséricordes divines aient part à la société des apôtres et des martyrs. La demande est humble : la récompense n'est pas revendiquée au titre du mérite personnel, mais implorée par le pardon et l'admission en Jésus-Christ. Les fidèles trouvent ainsi une prière d'espérance et de conversion au cœur du Canon silencieux. [Rite de 1962](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Guéranger](https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/)."}}],"canon":{"question":"Why does a Canon full of saints and divine glory return to the confession of one's own sinfulness?","text":"The priest breaks the prevailing silence of the Canon at its opening words, strikes his breast, and asks for fellowship with apostles and martyrs. The decisive words reject the presumption of deserving such a reward through one's own merit. Guéranger observes the gesture and reports practices of the faithful, but historical custom must not be imposed as universal posture or action in a 1962 congregation. The theological logic is not embarrassment after Consecration: the Eucharistic offering establishes precisely the ground of hope for sinners.","transition":"The Canon's closing sentences turn from petition to praise through the one mediator, Christ.","sources":{"guérangerOriginalFrench":["FRG24","FRG48","FRG49"],"stAlphonsusOriginalPrinted":[],"otherOriginalAuthorCritical":[],"inheritedBilingualManuscripts":["MM-NEW-15"]}},"biblicalScenes":[],"scripture":[],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"}],"special":[]},{"id":"AO.CANON.13","title":"Per quem haec omnia","studies":[{"id":"MM-NEW-16","short":{"en":"Every good gift through Christ [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"Tout bien nous vient par le Christ [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."},"deep":{"en":"Per quem haec omnia acknowledges that through Christ God creates, sanctifies, gives life, blesses and bestows all these good things. The priest makes three signs of the Cross over the Host and chalice at sanctificas, vivificas and benedicis; these do not consecrate again. The precise referent of haec omnia has received differing historical interpretations, including a possible association with blessings of material gifts in earlier usage. That proposed origin should not be taught as certain or imposed on the 1962 rite. [Roman Canon text and rubrics](https://en.wikipedia.org/wiki/Text_and_rubrics_of_the_Roman_Canon) · [Catholic Encyclopedia, Canon of the Mass (historical interpretation)](https://www.newadvent.org/cathen/03255c.htm).","fr":"Dans Per quem haec omnia, l'Église reconnaît que, par le Christ, Dieu crée, sanctifie, vivifie, bénit et nous accorde tous ces biens. Le prêtre trace trois signes de croix sur l'Hostie et le calice aux mots sanctificas, vivificas et benedicis ; il ne s'agit pas de nouvelles consécrations. Le sens précis de haec omnia a donné lieu à diverses interprétations historiques, dont un rapprochement possible avec d'anciennes bénédictions de biens matériels. Cette hypothèse d'origine ne doit pas être présentée comme certaine ni confondue avec les rubriques de 1962. [Texte et rubriques du Canon romain](https://en.wikipedia.org/wiki/Text_and_rubrics_of_the_Roman_Canon) · [Catholic Encyclopedia, Canon de la Messe (interprétation historique)](https://www.newadvent.org/cathen/03255c.htm)."}}],"canon":{"question":"What are 'all these good things' and why does the priest make signs of the Cross after Consecration?","text":"The words name God as the giver of creation, sanctification, life and blessing through Christ. Guéranger recalls a historical association with blessings of additional material gifts; this requires evidence rather than a confident reconstruction of what every ancient Mass celebrated. The three crosses belong to the actual 1962 ceremonial sequence but are not a repeated Consecration. This prayer therefore juxtaposes the whole created order and the Eucharistic gift without authorizing picturesque invented rites.","transition":"The final doxology gathers the whole sacrifice into an act of honour and glory to the Father.","sources":{"guérangerOriginalFrench":["FRG50","FRG51"],"stAlphonsusOriginalPrinted":[],"otherOriginalAuthorCritical":[],"inheritedBilingualManuscripts":["MM-NEW-16"]}},"biblicalScenes":["SH01"],"scripture":[],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"}],"special":[]},{"id":"AO.CANON.14","title":"Per ipsum · Minor Elevation","studies":[{"id":"MM-NEW-17","short":{"en":"All honour and glory to the Father [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"Tout honneur et toute gloire au Père [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."},"deep":{"en":"In Per ipsum the priest performs the lesser elevation with the consecrated Host and chalice during the final doxology of the Canon: through Christ, with Him and in Him, honour and glory are given to the Father in the unity of the Holy Ghost. This lesser elevation is not another consecration. It brings the long Eucharistic prayer to its liturgical conclusion and is ratified by the prescribed response Amen. [1962 rite](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Guéranger](https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/).","fr":"Dans le Per ipsum, le prêtre accomplit la petite élévation avec l'Hostie consacrée et le calice pendant la doxologie finale du Canon : par le Christ, avec lui et en lui, tout honneur et toute gloire sont rendus au Père dans l'unité du Saint-Esprit. Cette petite élévation n'est pas une nouvelle consécration. Elle conduit la longue prière eucharistique à sa conclusion liturgique, ratifiée par l'Amen prescrit. [Rite de 1962](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Guéranger](https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/)."}}],"canon":{"question":"Why does the Canon end with another elevation, and what is being offered to the Father?","text":"The words glorify the Father through Christ, with Him and in Him, in the unity of the Holy Ghost. Guéranger distinguishes the small elevation associated with this doxology from the ostension immediately after each Consecration. The crosses and actions have exact 1962 positions; they neither reconsecrate the sacred species nor restage another event in Christ's earthly life. The theological movement is complete: the Church's prayer, united to Christ's own self-offering, reaches its doxological conclusion.","transition":"The Pater noster now leads the celebration toward Communion, where sacrificial participation is received under the sacramental species.","sources":{"guérangerOriginalFrench":["FRG25","FRG52","FRG53"],"stAlphonsusOriginalPrinted":[],"otherOriginalAuthorCritical":[],"inheritedBilingualManuscripts":["MM-NEW-17"]}},"biblicalScenes":["SH01","SH24"],"scripture":[],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"}],"special":[]},{"id":"AO.CARD.019","title":"Pater noster","studies":[{"id":"MM-PRIMARY-MB21","short":{"en":"The Pater noster places the Lord's own prayer immediately before Communion. [Scripture](https://www.newadvent.org/bible/mat006.htm).","fr":"Le Pater noster place la prière enseignée par le Seigneur juste avant la Communion. [Écriture](https://www.newadvent.org/bible/mat006.htm)."},"deep":{"en":"After the Canon, the priest prays the words Christ taught his disciples. The Our Father joins adoration of God's name, longing for his kingdom, daily bread, forgiveness and deliverance from evil (Matthew 6:9–13; Luke 11:2–4). The printed 1962 Latin Missal has “panem nostrum cotidianum,” corresponding in sense to Luke's “quotidianum”; the Clementine Matthew reads “supersubstantialem.” The Lord's Prayer is thus proclaimed in its received Roman liturgical form. [Scripture](https://www.newadvent.org/bible/mat006.htm) · [Original 1962 Roman Missal page](https://gregobase.selapa.net/sources/42/395.png).","fr":"Après le Canon, le prêtre récite la prière que Jésus a enseignée à ses disciples. Le Notre Père unit l’adoration du nom divin, l’attente du Règne, la demande du pain, le pardon et la délivrance du mal (Mt 6,9–13 ; Lc 11,2–4). Dans le texte latin du Missel de 1962, on lit « panem nostrum cotidianum », comme le sens du « quotidianum » de Luc ; la Vulgate clémentine de Matthieu dit « supersubstantialem ». La prière demeure celle du Seigneur, sous sa forme liturgique romaine. [Écriture](https://www.newadvent.org/bible/mat006.htm) · [Missel romain de 1962, page originale](https://gregobase.selapa.net/sources/42/395.png)."}}],"canon":null,"biblicalScenes":[],"scripture":[],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"},{"title":"Lanslots · Illustrated Explanation (1897)","url":"https://archive.org/stream/illustratedexpla00lans/illustratedexpla00lans_djvu.txt"}],"special":[]},{"id":"AO.CARD.020","title":"Libera nos · Fraction · Pax Domini","studies":[{"id":"MM-NEW-18","short":{"en":"Deliverance, peace, and the commingling [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"Délivrance, paix et mélange des espèces [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."},"deep":{"en":"Libera nos expands the last petition of the Lord's Prayer, asking deliverance from past, present and future evils through the saints' intercession. The Fraction breaks the consecrated Host; the Pax Domini wishes the Lord's peace. At the commingling a small particle enters the chalice: the word consecratio in that prayer does not mean a second Eucharistic Consecration. The successive actions possess distinct meanings and must not be collapsed into one invented gesture. At Requiem Mass, the prayer Domine Iesu Christe, qui dixisti Apostolis tuis is omitted and the kiss of peace is not given. [1962 rite](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Guéranger](https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/) · [Scripture](https://www.newadvent.org/bible/mat006.htm). [1962 Mass and Requiem rubrics](https://1962ordo.today/1962-rubrics/).","fr":"Le Libera nos développe la dernière demande du Notre Père, implorant la délivrance des maux passés, présents et futurs avec l'intercession des saints. La fraction divise l'Hostie consacrée ; le Pax Domini souhaite la paix du Seigneur. Lors du mélange, une parcelle est déposée dans le calice : le mot consecratio de cette prière ne signifie pas une seconde Consécration eucharistique. Ces gestes successifs ont leur sens propre et ne doivent pas être confondus. À la messe des défunts, la prière Domine Iesu Christe, qui dixisti Apostolis tuis est omise et le baiser de paix n'est pas donné. [Rite de 1962](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Guéranger](https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/) · [Écriture](https://www.newadvent.org/bible/mat006.htm). [Rubriques de la Messe de 1962 et des défunts](https://1962ordo.today/1962-rubrics/)."}}],"canon":null,"biblicalScenes":[],"scripture":["Matthew 6:13"],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"},{"title":"Lanslots · Illustrated Explanation (1897)","url":"https://archive.org/stream/illustratedexpla00lans/illustratedexpla00lans_djvu.txt"}],"special":["FRACTION_COMMIXTURE_NOT_SECOND_TRANSUBSTANTIATION"]},{"id":"AO.CARD.021","title":"Agnus Dei","studies":[{"id":"MM-PRIMARY-MB23","short":{"en":"The Agnus Dei invokes Christ as the Lamb who takes away the world's sin. [Scripture](https://www.newadvent.org/bible/joh001.htm).","fr":"L'Agnus Dei invoque le Christ, Agneau qui enlève le péché du monde. [Écriture](https://www.newadvent.org/bible/joh001.htm)."},"deep":{"en":"John the Baptist points to Jesus as “the Lamb of God, who takes away the sin of the world” (John 1:29). Before Communion the Church addresses Christ as the sacrificial Lamb who saves, asking first for mercy and then peace. At Masses for the Dead the petitions ask instead for the souls' rest: “dona eis requiem” and finally “dona eis requiem sempiternam.” The celebrant also omits the ordinary breast strikes at the Requiem Agnus Dei. The same biblical title thus serves differing liturgical intentions. [Scripture](https://www.newadvent.org/bible/joh001.htm) · [Original 1962 Roman Missal page](https://gregobase.selapa.net/sources/42/400.png). [1962 Requiem rubrics](https://1962ordo.today/1962-rubrics/).","fr":"En désignant Jésus, Jean-Baptiste annonce : « Voici l’Agneau de Dieu, qui enlève le péché du monde » (Jn 1,29). Avant la Communion, l’Église s’adresse au Christ comme à la victime offerte pour le salut et implore sa miséricorde puis sa paix. Aux Messes des défunts, les demandes deviennent une supplication pour le repos des âmes : « dona eis requiem », puis « dona eis requiem sempiternam ». Le prêtre omet également les frappements de poitrine habituels à l'Agnus Dei des défunts. Le même titre biblique nourrit ainsi des intentions liturgiques différentes. [Écriture](https://www.newadvent.org/bible/joh001.htm) · [Missel romain de 1962, page originale](https://gregobase.selapa.net/sources/42/400.png). [Rubriques de la Messe des défunts](https://1962ordo.today/1962-rubrics/)."}}],"canon":null,"biblicalScenes":["SH06","SH11","SH15"],"scripture":["John 1:29"],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"},{"title":"Lanslots · Illustrated Explanation (1897)","url":"https://archive.org/stream/illustratedexpla00lans/illustratedexpla00lans_djvu.txt"}],"special":[]},{"id":"AO.CARD.022","title":"Prayers before Communion","studies":[{"id":"MM-PRIMARY-MB24","short":{"en":"The priest repeats the centurion's act of humble faith before his own Communion. [Scripture](https://www.newadvent.org/bible/mat008.htm).","fr":"Le prêtre reprend l'acte de foi humble du centurion avant sa propre Communion. [Écriture](https://www.newadvent.org/bible/mat008.htm)."},"deep":{"en":"A centurion acknowledges Jesus' authority and says he is unworthy to receive him under his roof: one word from the Lord can heal his servant (Matthew 8:8). Before Communion the priest takes up this profession of trust and humility: “Domine, non sum dignus,” asking for the healing of his own soul. The Gospel speaks of “puer meus,” the servant; the Mass applies the petition to “anima mea,” the communicant's soul. [Scripture](https://www.newadvent.org/bible/mat008.htm) · [Original 1962 Roman Missal page](https://gregobase.selapa.net/sources/42/402.png).","fr":"Un centurion reconnaît l’autorité de Jésus et déclare qu’il n’est pas digne de le recevoir sous son toit ; une seule parole du Seigneur peut guérir son serviteur (Mt 8,8). Avant la Communion, le prêtre reprend cette confession de confiance et d’humilité : « Domine, non sum dignus », puis demande la guérison de son âme. L’Évangile parle du serviteur, « puer meus » ; la Messe applique la demande au communiant, « anima mea ». [Écriture](https://www.newadvent.org/bible/mat008.htm) · [Missel romain de 1962, page originale](https://gregobase.selapa.net/sources/42/402.png)."}},{"id":"MM-PRIMARY-N05","short":{"en":"Christ's promised peace is invoked for the unity of his Church before Communion. [Scripture](https://www.newadvent.org/bible/joh014.htm).","fr":"La paix promise par le Christ est implorée pour l'unité de son Église avant la Communion. [Écriture](https://www.newadvent.org/bible/joh014.htm)."},"deep":{"en":"Before Communion, the prayer “Domine Iesu Christe, qui dixisti Apostolis tuis” takes up Jesus' promise: “Peace I leave with you; my peace I give to you” (John 14:27). The priest asks the Lord to look not upon human sins but upon the faith of his Church, granting her unity and peace. Christ's peace is a gift deeper than the mere absence of conflict. Under the 1962 rite this prayer and the kiss of peace are omitted at Masses for the Dead. [Scripture](https://www.newadvent.org/bible/joh014.htm) · [Original 1962 Roman Missal page](https://gregobase.selapa.net/sources/42/400.png). [1962 Requiem rubrics](https://1962ordo.today/1962-rubrics/).","fr":"Avant la Communion, la prière « Domine Iesu Christe, qui dixisti Apostolis tuis » reprend la promesse de Jésus aux siens : « Je vous laisse la paix, je vous donne ma paix » (Jn 14,27). Le prêtre demande alors au Seigneur de ne pas regarder les péchés de chacun, mais la foi de son Église, et de lui accorder l’unité et la paix. Cette paix est un don du Christ, plus profond que la seule absence de conflit. Cette prière et le baiser de paix sont omis aux Messes des défunts selon le rite de 1962. [Écriture](https://www.newadvent.org/bible/joh014.htm) · [Missel romain de 1962, page originale](https://gregobase.selapa.net/sources/42/400.png). [Rubriques de la Messe des défunts](https://1962ordo.today/1962-rubrics/)."}}],"canon":null,"biblicalScenes":["SH16"],"scripture":["Matthew 8:8"],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"},{"title":"Lanslots · Illustrated Explanation (1897)","url":"https://archive.org/stream/illustratedexpla00lans/illustratedexpla00lans_djvu.txt"}],"special":["PRIEST_DOMINE_NON_SUM_DIGNUS_NOT_FAITHFUL_RESPONSE"]},{"id":"AO.CARD.023","title":"Communion of the Priest","studies":[{"id":"MM-PRIMARY-MB25","short":{"en":"Before the Precious Blood, the priest gives thanks with the psalm's chalice of salvation. [Scripture](https://www.studybible.info/Clementine_Vulgate/Psalms%20115:3-8).","fr":"Avant le Précieux Sang, le prêtre rend grâce avec le psaume du calice du salut. [Écriture](https://www.studybible.info/Clementine_Vulgate/Psalms%20115:3-8)."},"deep":{"en":"Before receiving the Precious Blood, the priest takes up the gratitude of Vulgate Psalm 115: “What shall I render to the Lord for all he has given me? I will take the chalice of salvation” (Psalm 115:3–4). In the psalm these words express thanksgiving for God's deliverance; in the Mass they accompany Communion from Christ's chalice. In many modern Bibles the passage is numbered Psalm 116:12–13. [Scripture](https://www.studybible.info/Clementine_Vulgate/Psalms%20115:3-8) · [Original 1962 Roman Missal page](https://gregobase.selapa.net/sources/42/403.png).","fr":"Avant de recevoir le Précieux Sang, le prêtre reprend la gratitude du psaume 115 de la Vulgate : « Que rendrai-je au Seigneur pour tous les biens qu’il m’a faits ? Je prendrai le calice du salut » (Ps 115,3–4). Dans le psaume, ces mots expriment l’action de grâces pour la délivrance accordée par Dieu ; dans la Messe, ils accompagnent la Communion au calice du Christ. La numérotation correspond souvent à Ps 116,12–13 dans les Bibles modernes. [Écriture](https://www.studybible.info/Clementine_Vulgate/Psalms%20115:3-8) · [Missel romain de 1962, page originale](https://gregobase.selapa.net/sources/42/403.png)."}}],"canon":null,"biblicalScenes":["SH07","SH16"],"scripture":[],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"},{"title":"Lanslots · Illustrated Explanation (1897)","url":"https://archive.org/stream/illustratedexpla00lans/illustratedexpla00lans_djvu.txt"}],"special":[]},{"id":"AO.CARD.024","title":"Ecce Agnus Dei & Faithful Preparation","studies":[{"id":"MM-NEW-19","short":{"en":"Prepare to receive the Lord [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"Se préparer à recevoir le Seigneur [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."},"deep":{"en":"When Communion is to be distributed to the faithful, the liturgy has its own preparation distinct from the priest's earlier private prayers. The 'Ecce Agnus Dei' and the faithful's 'Domine, non sum dignus' invite a confession of faith and humility before Christ truly present. The additional Confiteor found in older or some local usages is not prescribed for the faithful's Communion in the 1962 Missal; nor may the priest's earlier repetitions be assigned automatically to the congregation. [1962 rite](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Scripture](https://www.newadvent.org/bible/1co011.htm). [1962 Mass and Requiem rubrics](https://1962ordo.today/1962-rubrics/).","fr":"Lorsque la Communion doit être distribuée aux fidèles, la liturgie prévoit une préparation distincte des prières privées récitées auparavant par le prêtre. L'« Ecce Agnus Dei » et le « Domine, non sum dignus » des fidèles invitent à une profession de foi et d'humilité devant le Christ réellement présent. Le second Confiteor, présent dans des usages anciens ou locaux, n'est pas prescrit pour la distribution de la Communion par le Missel de 1962 et ne doit donc pas être présenté comme une obligation liturgique universelle ; les répétitions distinctes du prêtre ne doivent pas non plus être transférées à l'assemblée. [Rite de 1962](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Écriture](https://www.newadvent.org/bible/1co011.htm). [Rubriques de la Messe de 1962 et des défunts](https://1962ordo.today/1962-rubrics/)."}}],"canon":null,"biblicalScenes":["SH15","SH16"],"scripture":[],"authorLinks":[],"special":["SECOND_CONFITEOR_OLDER_OR_LOCAL_CUSTOM_NOT_UNIVERSALLY_MANDATORY"]},{"id":"AO.CARD.025","title":"Communion of the Faithful","studies":[{"id":"MM-NEW-20","short":{"en":"Communion is a sacred participation [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"La Communion est une participation sacrée [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."},"deep":{"en":"The faithful who receive Holy Communion truly receive the living Christ, whose sacrifice has been offered on the altar. Worthy reception asks for faith, preparation and reverence; St Paul warns against eating and drinking unworthily. Communion of the faithful is highly recommended, but the Eucharistic sacrifice does not depend upon every member of the congregation communicating. The actual distribution takes place only when communicants are present and according to the applicable rite. [1962 rite](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Scripture](https://www.newadvent.org/bible/1co011.htm).","fr":"Les fidèles qui communient reçoivent réellement le Christ vivant, dont le Sacrifice a été offert à l'autel. Une réception digne demande la foi, la préparation et le respect ; saint Paul avertit contre une communion indigne. La Communion des fidèles est vivement recommandée, mais l'existence du Sacrifice eucharistique ne dépend pas de la communion de chaque assistant. La distribution a lieu lorsque des communiants sont présents, selon le rite applicable. [Rite de 1962](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Écriture](https://www.newadvent.org/bible/1co011.htm)."}}],"canon":null,"biblicalScenes":["SH07","SH16","SH21","SH23","SH24"],"scripture":[],"authorLinks":[{"title":"Lanslots · Illustrated Explanation (1897)","url":"https://archive.org/stream/illustratedexpla00lans/illustratedexpla00lans_djvu.txt"}],"special":["FAITHFUL_COMMUNION_MAY_NOT_TAKE_PLACE"]},{"id":"AO.CARD.026","title":"Ablutions & Communion Antiphon","studies":[{"id":"MM-NEW-21","short":{"en":"What we have received [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"Ce que nous avons reçu [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."},"deep":{"en":"During the ablutions, the celebrant receives the prescribed purifications and prays that what has passed his lips may be received with a pure mind and bring an enduring spiritual remedy. The Communion antiphon belongs to the variable Proper and cannot be supplied from one unchanging example. This part of the Mass teaches that the sacramental gift should bear fruit beyond the brief moments of Communion. [1962 rite](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Guéranger](https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/).","fr":"Pendant les ablutions, le célébrant accomplit les purifications prescrites et demande que ce qu'il a reçu de la bouche soit accueilli avec une âme pure et lui procure un remède durable. L'antienne de Communion appartient au Propre variable et ne peut être remplacée par un exemple uniforme. Cette partie de la Messe enseigne que le don sacramentel doit porter du fruit bien au-delà des instants de la Communion. [Rite de 1962](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Guéranger](https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/)."}}],"canon":null,"biblicalScenes":[],"scripture":[],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"}],"special":[]},{"id":"AO.CARD.027","title":"Postcommunion","studies":[{"id":"MM-NEW-22","short":{"en":"The Church gives thanks [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"L'Église rend grâce [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."},"deep":{"en":"In the Postcommunion prayer the Church asks that the Sacrament received accomplish its fruit in those who have shared in the holy mysteries. This liturgical thanksgiving is not the same as a person's own thanksgiving after Mass: both have a proper place. The particular words are those appointed for the day, with any lawful additional orations; the generic explanation should not replace them. [1962 rite](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Guéranger](https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/) · [Scripture](https://www.newadvent.org/bible/col003.htm).","fr":"Dans la Postcommunion, l'Église demande que le Sacrement reçu produise ses fruits chez ceux qui ont participé aux saints mystères. Cette action de grâces liturgique ne se confond pas avec l'action de grâces personnelle après la Messe : chacune a sa place. Les paroles sont celles qui sont prescrites pour le jour, avec les oraisons supplémentaires permises ; une explication générale ne les remplace pas. [Rite de 1962](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Guéranger](https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/) · [Écriture](https://www.newadvent.org/bible/col003.htm)."}}],"canon":null,"biblicalScenes":[],"scripture":[],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"}],"special":[]},{"id":"AO.CARD.028","title":"Dismissal","studies":[{"id":"MM-NEW-23","short":{"en":"The dismissal is not always identical [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"Le renvoi n'est pas toujours identique [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."},"deep":{"en":"The dismissal concludes the public liturgical action with the formula appropriate to the day or rite. Ite, missa est is not interchangeable with Benedicamus Domino or Requiescant in pace (the Requiem dismissal); special liturgies and subsequent actions can also modify what follows. Its practical lesson is to carry the worship of God into one's duties, without presenting that application as the linguistic origin of missa. [1962 rite](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/). [1962 Mass and Requiem rubrics](https://1962ordo.today/1962-rubrics/).","fr":"Le renvoi conclut l'action liturgique publique par la formule qui convient au jour ou au rite. Ite, missa est ne se substitue pas indifféremment à Benedicamus Domino ou à Requiescant in pace (le renvoi de la Messe des défunts) ; certaines liturgies ou actions qui suivent modifient aussi la conclusion. L'application pratique est de prolonger le culte rendu à Dieu par la fidélité à ses devoirs, sans ériger cette méditation en étymologie du mot missa. [Rite de 1962](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/). [Rubriques de la Messe de 1962 et des défunts](https://1962ordo.today/1962-rubrics/)."}}],"canon":null,"biblicalScenes":[],"scripture":[],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"}],"special":["DISMISSAL_VARIANT_BY_MASS_TYPE_OR_FOLLOWING_ACTION"]},{"id":"AO.CARD.029","title":"Placeat & Final Blessing","studies":[{"id":"MM-NEW-24","short":{"en":"The prayer and blessing after the dismissal [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/).","fr":"La prière et la bénédiction après le renvoi [Source](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/)."},"deep":{"en":"Through Placeat the celebrant asks the Holy Trinity to receive the sacrifice accomplished and make it fruitful for those for whom it was offered. The final blessing is a separate prescribed action when the rite includes it; it is not implied simply because the dismissal has sounded. At a Requiem Mass the final blessing is omitted, but the Last Gospel is ordinarily read; it would be incorrect to infer that Requiem itself suppresses the Last Gospel. Distinct special liturgical continuations require their own rubrical review. [1962 rite](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Guéranger](https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/). [1962 Mass and Requiem rubrics](https://1962ordo.today/1962-rubrics/).","fr":"Par le Placeat, le célébrant demande à la Sainte Trinité d'agréer le Sacrifice accompli et d'en faire bénéficier ceux pour qui il a été offert. La bénédiction finale est un geste distinct lorsqu'elle est prescrite ; elle ne découle pas automatiquement du renvoi. À la messe des défunts, la bénédiction finale est omise, mais le Dernier Évangile se lit ordinairement : on ne peut donc pas prétendre que la messe de Requiem le supprime en tant que telle. Les autres conclusions liturgiques particulières doivent être examinées selon leurs propres rubriques. [Rite de 1962](https://archive.ccwatershed.org/pdfs/5276-ritus-servandus-translated-english/download/) · [Guéranger](https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/). [Rubriques de la Messe de 1962 et des défunts](https://1962ordo.today/1962-rubrics/)."}}],"canon":null,"biblicalScenes":[],"scripture":[],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"}],"special":["FINAL_BLESSING_CAN_BE_SUPPRESSED_BY_SPECIAL_RITE_OR_REQUIEM"]},{"id":"AO.CARD.030","title":"Last Gospel","studies":[{"id":"MM-PRIMARY-MB26","short":{"en":"When prescribed, the Last Gospel returns us to the mystery of the Word made flesh. [Scripture](https://www.newadvent.org/bible/joh001.htm).","fr":"Lorsqu'il est prescrit, le Dernier Évangile nous ramène au mystère du Verbe fait chair. [Écriture](https://www.newadvent.org/bible/joh001.htm)."},"deep":{"en":"When prescribed, the Mass concludes with St John's Prologue: in the beginning was the Word, the Word was God, and the Word became flesh and dwelt among us (John 1:1–14). This reading returns the whole celebration to the mystery of the Incarnation, the beginning of our salvation. The genuflection at “Et Verbum caro factum est” expresses adoration of the Word made flesh. The 1962 Missal also specifies celebrations on which this Last Gospel is omitted. [Scripture](https://www.newadvent.org/bible/joh001.htm) · [Original 1962 Roman Missal page](https://gregobase.selapa.net/sources/42/409.png).","fr":"Lorsque les rubriques le prescrivent, la Messe se conclut par le Prologue de saint Jean : au commencement était le Verbe, le Verbe était Dieu, et le Verbe s’est fait chair pour habiter parmi nous (Jn 1,1–14). Cette lecture ramène toute la célébration au mystère de l’Incarnation, source de notre salut. La génuflexion à « Et Verbum caro factum est » exprime l’adoration du Verbe incarné. Le Missel de 1962 prévoit toutefois des célébrations où ce dernier Évangile est omis. [Écriture](https://www.newadvent.org/bible/joh001.htm) · [Missel romain de 1962, page originale](https://gregobase.selapa.net/sources/42/409.png)."}}],"canon":null,"biblicalScenes":["SH13"],"scripture":["John 1:1–14"],"authorLinks":[{"title":"Dom Guéranger · Explication des prières","url":"https://www.domgueranger.net/explication-des-prieres-de-la-sainte-messe-2/"},{"title":"Lanslots · Illustrated Explanation (1897)","url":"https://archive.org/stream/illustratedexpla00lans/illustratedexpla00lans_djvu.txt"}],"special":["LAST_GOSPEL_NOT_UNIVERSALLY_PRESENT"]}]});
